  [312] = { name="真海外仙丹", kind="药物", sub="内力上限", price=15000, exp=400000, grade="1", attrs="[5, 0, 0, 0]", desc="虬髯客采海外精华提炼的至品丹药, 药力远胜寻常海外仙丹, 服之可拓宽经脉、增长五点内力上限(内力修为已臻极限者无效)" },
  [313] = { name="小还丹", kind="药物", sub="内力", price=5000, exp=200000, grade="1", attrs="[200, 0, 0, 0]", desc="全真教秘制丹药, 服之内息充盈, 可恢复二百点内力" },
  [314] = { name="大还丹", kind="药物", sub="内力", price=20000, exp=800000, grade="1", attrs="[1000, 0, 0, 0]", desc="少林寺炼制的疗伤圣药, 药力雄浑, 可恢复一千点内力" },
  [315] = { name="黑玉断续膏", kind="药物", sub="生命", price=30000, exp=1000000, grade="1", attrs="[80, 0, 0, 0]", desc="西域奇药, 色如黑玉, 专治筋断骨折的重伤, 可恢复八成内伤" },
  [316] = { name="九花玉露丸", kind="药物", sub="内力", price=12000, exp=500000, grade="1", attrs="[500, 0, 0, 0]", desc="桃花岛以九种花瓣炼制的药丸, 清香扑鼻, 可恢复五百点内力" },
  [317] = { name="珍品药盒", kind="其他", sub="抽奖", price=25000, exp=0, grade="1", attrs="{}", desc="一只描金乌木药盒, 内分八格, 收着金创药、生肌膏、小还丹、大还丹等各色珍品药物, 打开可得其一." },
  [318] = { name="神功残卷", kind="书籍", sub="", price=0, exp=0, grade="1", attrs="[0, 0, 0, 0]", desc="一部记载夺人内力秘法的残卷,字里行间似有吞吸之力" },
  [319] = { name="积分刮刮乐", kind="其他", sub="属性增加类", price=0, exp=0, grade="1", attrs="{}", desc="花积分买来的一张刮刮乐,刮开涂层便知惊喜,据说能刮出积分" },
  [320] = { name="齐眉棍", kind="武器", sub="棍", price=4000, exp=160000, grade="2", attrs="[55, 0, 0, 0]", desc="棍身以白蜡木制成,坚韧而有弹性,长与眉齐,故名齐眉棍。舞动时棍影浑圆,攻守兼备。" },
  [321] = { name="银轮", kind="武器", sub="刀", price=150000, exp=300000, grade="4", attrs="[110, 0, 3, -2]", desc="西域密宗的银刚法轮, 轮身泛着冷银光泽, 锋刃薄而利, 较金轮稍轻, 出手更疾。" },
  [322] = { name="铜轮", kind="武器", sub="刀", price=30000, exp=300000, grade="3", attrs="[85, 0, 2, -1]", desc="密宗铜制法轮, 轮缘厚重, 转动时嗡嗡作响, 力道沉猛, 削中者骨断筋折。" },
  [323] = { name="铁轮", kind="武器", sub="刀", price=30000, exp=300000, grade="3", attrs="[70, 0, 1, -2]", desc="密宗铁铸法轮, 朴拙无饰, 唯分量极沉, 专以力压人, 一撞之下势不可当。" },
  [324] = { name="铅轮", kind="武器", sub="刀", price=30000, exp=300000, grade="3", attrs="[70, 0, 0, -3]", desc="密宗铅制法轮, 色暗质软, 是五轮中最钝重的一枚, 舞动时风声沉闷, 却最是耐磨。" },
  [325] = { name="碧水剑", kind="武器", sub="剑", price=30000, exp=220000, grade="3", attrs="[78, 0, 3, 2]", desc="剑身如一泓碧水, 寒光凛冽, 是岳不群收藏的名剑, 因爱女灵珊喜爱而相赠。剑出鞘时寒气逼人, 中者血脉凝滞。" },
  [326] = { name="九尾狐", kind="武器", sub="鞭", price=150000, exp=200000, grade="4", attrs="[68, 0, 3, 1]", desc="鞭身以碧玉丝缠就,尾端缀作狐尾之形,舞动时碧光流动妖异惑目,是碧眼狐狸自炼的随身软鞭。" },
  [327] = { name="赤凰剑", kind="武器", sub="剑", price=30000, exp=250000, grade="3", attrs="[85, 0, 5, 1]", desc="剑身赤如丹火,剑格铸作凤首之形,出鞘时隐带热浪,乃取南方赤凰之意。中者如遭火燎,肌肤焦灼。" },
  [328] = { name="青龙刀", kind="武器", sub="刀", price=30000, exp=250000, grade="3", attrs="[80, 0, 5, 1]", desc="刀身修长如龙脊,通体泛着青幽冷光,刀背錾有层层鳞纹。挥出时隐有龙吟,中者气力涣散。" },
  [329] = { name="白虎鞭", kind="武器", sub="鞭", price=30000, exp=250000, grade="3", attrs="[90, 0, 5, 1]", desc="鞭身白亮如虎尾,以精钢抽丝缠就,节节分明。甩动时啸声如虎吼,中者血脉凝滞如坠冰窟。" },
  [330] = { name="玄武杖", kind="武器", sub="杖", price=30000, exp=250000, grade="3", attrs="[80, 0, 5, 1]", desc="杖身乌沉厚重,杖头雕作玄武之形,双目嵌青石。杖影过处阴寒透骨,令人心神失守。" },
  [331] = { name="麒麟棍", kind="武器", sub="棍", price=30000, exp=250000, grade="3", attrs="[70, 0, 5, 1]", desc="棍身乌沉如古木,通体錾有金丝麟纹,顶端铸作麒麟之首。挥动时隐有雷音,中者经脉滞涩,筋骨麻痹。" },
  [2001] = { name="精炼炭", kind="其他", sub="强化", price=100, exp=0, grade="1", attrs="[0, 0, 0, 0]", desc="锻造用的上等精炼炭,火力持久而沉稳,是强化装备不可或缺的材料" },
  [10001] = { name="月饼", kind="食物", sub="", price=100, exp=10, grade="1", attrs="[500, 500, 0, 0]", desc="中秋节的节令吃食,饼皮金黄,内馅甜糯,一口下去满是节日的味道。" },
  [10002] = { name="桂花酒", kind="药物", sub="内力", price=5000, exp=10, grade="1", attrs="[5000, 0, 0, 0]", desc="中秋时节酿的桂花酒,开坛清香四溢,饮之如沐月华,内力翻涌。" },
  [10003] = { name="国庆围巾", kind="装备", sub="头盔", price=30000, exp=10, grade="3", attrs="[0, 5, 3, 2]", desc="普天同庆的节日纪念围巾,红底金字绣着「国庆」二字,围上暖意融融,喜气洋洋。" },
}
