  [106] = { name="独孤九剑", type="剑法", weapon="剑", desc="剑魔独孤求败所创，剑招只攻不守，专找对手招式破绽，不靠内力取胜" },
  [107] = { name="打狗棒法", type="棍法", weapon="棍", desc="丐帮镇帮绝学" },
  [108] = { name="全真剑法", type="剑法", weapon="剑", desc="全真教开派剑术，重阳真人所传，讲究阴阳相济、后发先至，不求奇诡但根基极正" },
  [109] = { name="辟邪剑法", type="剑法", weapon="剑", desc="林远图自葵花宝典残页所悟，剑招阴柔诡谲、快到无从捉摸，然习者须先自断根本" },
  [110] = { name="玉女素心剑", type="剑法", weapon="剑", desc="古墓派林朝英所创，本为双人合击之术，剑势轻灵飘忽如落花回风，柔中带韧" },
  [111] = { name="金蛇剑法", type="剑法", weapon="剑", desc="金蛇郎君夏雪宜所创，剑招灵动如毒蛇吐信，专走偏锋刁钻毒辣，配金蛇锥更是难防" },
  [112] = { name="峨眉剑法", type="剑法", weapon="剑", desc="郭襄开峨眉一派，剑法兼采九阳真经与古墓遗意，轻灵中带峻烈，女子使来最见锋芒" },
  [113] = { name="胡家刀法", type="刀法", weapon="刀", desc="辽东胡家世代相传，刀势朴拙无华却狠辣绝伦，招招不留余地，与苗家剑法互为死敌" },
  [114] = { name="血刀刀法", type="刀法", weapon="刀", desc="血刀门不传之秘，刀法凶残酷烈血气冲天，专攻不守，善以刀身黏缠夺人兵刃" },
  [115] = { name="七伤拳", type="拳脚", weapon="", desc="崆峒派镇派绝学，一拳七劲交错，敌受七伤己亦损七脏，修者非心性坚忍不可轻习" },
  [116] = { name="斗转星移", type="拳脚", weapon="", desc="姑苏慕容氏不传之秘，借敌之力还施敌身，敌招愈狠反噬愈重，非武学之攻乃武学之反" },
  [117] = { name="一阳指", type="拳脚", weapon="", desc="大理段氏世传指法，以纯阳内力自指端吐出，点穴疗伤两皆可用，为六脉神剑之根基" },
  [118] = { name="乾坤大挪移", type="拳脚", weapon="", desc="明教镇教神功，能挪移乾坤颠倒阴阳，借敌之力还施敌身，历代教主惟九阳护体者可大成" },
  [119] = { name="神照经", type="内功", weapon="", desc="梅念笙所传内功至宝，内息浑厚绵长生生不绝，纵经脉尽断亦能自愈重生，起死回生之效" },
  [120] = { name="寒冰真气", type="内功", weapon="", desc="至阴至寒的内家心法，真气所过之处经脉冻结血液凝滞，与人交手常带彻骨寒意" },
  [121] = { name="梯云纵", type="轻功", weapon="", desc="武当轻身功夫，借势腾挪如踏云梯拾级而上，纵跃间可离地数丈，落地无声" },
  [122] = { name="寒冰绵掌", type="拳脚", weapon="", desc="至阴至寒的绵柔掌法，掌到之处寒气侵体经脉冻凝，中者未觉其痛先觉其冷" },
  [123] = { name="战斗减伤", type="其他", weapon="", desc="临敌时周身劲力自然流转，卸去外来震劲，修为愈深受创愈轻" },
  [124] = { name="明教内功", type="内功", weapon="", desc="明教镇教内功心法，源于波斯总教，中土明教历代相传，内力浑厚绵长，运劲收发由心" },
  [125] = { name="蝠翼轻功", type="轻功", weapon="", desc="青翼蝠王韦一笑的成名绝技，身法展开如蝙蝠振翼，来去无声，倏忽千里，为当世轻功之冠" },
  [126] = { name="战斗吸气", type="其他", weapon="", desc="战斗中自动吐纳夺回生机：血量低于最大血量的武功等级百分比时，回合开始自动吸气，一次吸满到有效气血为止（不消耗回合，消耗内力，效率随等级）" },
  [127] = { name="九阴白骨爪", type="拳脚", weapon="", desc="《九阴真经》外门爪法，五指运劲如钢钩，抓处骨裂筋断，招式阴毒狠辣" },
  [128] = { name="九阴神功", type="内功", weapon="", desc="《九阴真经》总纲无上内功,阴柔绵长生生不息,催动外门爪掌威力倍增" },
  [253] = { name="九阳神功", type="内功", weapon="", desc="九阳神功是金庸笔下最刚猛纯阳的内功心法,练者内力源源不竭,至刚至阳,百毒不侵." },
  [254] = { name="大旗风云掌", type="拳脚", weapon="", desc="大旗门至高掌法,掌出如大旗招展、风云变色,刚猛沉雄,有铁血旌旗之气" },
  [129] = { name="螺旋九影", type="轻功", weapon="", desc="《九阴真经》轻身功夫，身形旋转间幻出九道残影，虚实难辨飘忽莫测" },
  [130] = { name="峨嵋九阳功", type="内功", weapon="", desc="峨眉派镇山内功，源自九阳真经一脉，内息浑厚正大，护体续航两皆可观" },
  [131] = { name="峨眉身法", type="轻功", weapon="", desc="峨眉派轻身功夫，身形轻灵飘逸，如峨眉云海翻卷，进退飘忽莫测" },
  [132] = { name="截手九式", type="拳脚", weapon="", desc="峨眉派截手功夫，九式连环专截敌招去路，掌爪并用以截为攻" },
  [133] = { name="易筋经", type="内功", weapon="", desc="少林寺镇寺之宝，达摩所创内功第一，能洗髓伐毛脱胎换骨，内力生生不息百毒难侵" },
  [134] = { name="招式防御", type="其他", weapon="", desc="临敌时劲力内敛收敛锋芒：敌方招式劲力的放大倍率按 (100-等级)% 保留，等级越高敌招加成越弱" },
  [135] = { name="战斗防御", type="其他", weapon="", desc="全身鼓荡真气护住要害：敌方伤害的基础加成部分按 (100-等级)% 保留，等级越高受创越轻" },
  [136] = { name="呆鸡恢复", type="其他", weapon="", desc="以深厚内息化去滞涩: 自身呆若木鸡时, 回合开始以武功等级/100 的概率提前脱离呆鸡, 恢复行动" },
  [137] = { name="战斗命中", type="其他", weapon="", desc="临敌出手精准狠辣：每级令自身武功等级在命中判定中 +1（与招式 ap 修正同处计算，直接加在武功等级上）" },
  [138] = { name="战斗增伤", type="其他", weapon="", desc="催动真气令出手愈发凌厉：伤害的基础加成部分 ×(1+等级/50)，等级越高增幅越大" },
  [139] = { name="招式增伤", type="其他", weapon="", desc="招式间的劲力愈发圆熟：武功招式的劲力放大倍率 ×(1+等级/50)，等级越高招式威力越强" },
  [140] = { name="基本枪法", type="枪法", weapon="枪", desc="枪法的基础" },
  [141] = { name="温侯戟法", type="枪法", weapon="枪", desc="温侯吕布名震天下的戟法,使开来如飞将军临阵,威风凛凛" },
  [142] = { name="紫霞神功", type="内功", weapon="", desc="华山派气宗至高内功心法,紫气东来,内力雄浑绵长,乃气宗不传之秘" },
  [143] = { name="蜻蜓点水", type="轻功", weapon="", desc="华山派轻功,身法轻灵如水,进退之间点到即止,如蜻蜓掠水不留痕迹" },
  [144] = { name="圣火令法", type="剑法", weapon="剑", desc="明教圣火令上所载的波斯武功,招法诡奇,火劲灼人,与中土剑法大异其趣" },
  [145] = { name="内力防吸", type="其他", weapon="", desc="内息自成周天，劲力内敛不泄，使外来的挤劲难以牵动己身内力" },
  [146] = { name="加力节约", type="其他", weapon="", desc="运劲发力时内力收放有度，同样威力的加力耗损更少，久战不竭" },
  [147] = { name="战斗回避", type="其他", weapon="", desc="临敌身法圆融，每级令自身轻功等级在闪避判定中 +1（与战斗命中同理，加在武功等级上，经立方放大）" },
  [148] = { name="战斗招架", type="其他", weapon="", desc="临敌守势绵密，每级令自身招架等级在招架判定中 +1（与战斗命中同理，加在武功等级上，经立方放大）" },
  [149] = { name="天鉴神功", type="内功", weapon="", desc="一门玄奥深厚的内家绝学,内息浩瀚如渊,运转间可鉴天地之机" },
  [150] = { name="金雁功", type="轻功", weapon="", desc="全真教轻身功夫,身法如金雁掠空,起落之间轻捷飘逸,进退从容" },
  [151] = { name="全真心法", type="内功", weapon="", desc="全真教筑基内功,澄心静虑、返璞归真,内息绵长醇正,最合道家清静之旨" },
  [152] = { name="三花聚顶掌", type="拳脚", weapon="", desc="全真教掌法绝学,聚精、气、神三花于顶门,掌力浑厚,一发动则周身真气奔涌" },
  [153] = { name="灵蛇拳", type="拳脚", weapon="", desc="白驼山绝学,拳势灵动诡谲如灵蛇吐信,身形游走,出招匪夷所思" },
  [154] = { name="神驼雪山掌", type="拳脚", weapon="", desc="白驼山掌法,掌力沉厚如雪山压顶,一式既出便铺天盖地,令人无处可避" },
  [155] = { name="瞬息千里", type="轻功", weapon="", desc="白驼山轻功,身法迅疾如白驹过隙,瞬息之间已掠出千里,令人难辨踪影" },
  [156] = { name="逆转经脉", type="内功", weapon="", desc="白驼山诡异内功,逆行经脉、颠倒气血,内息处处出人意表,练成后周身劲力不循常理" },
  [157] = { name="散手八扑", type="拳脚", weapon="", desc="宁道奇赖以成名的一路散手,不拘成法、随手拈来,八扑之间虚实相生,看似信手却处处杀机" },
  [158] = { name="先天罡气", type="内功", weapon="", desc="宁道奇所修的无上玄功,采先天一气凝为罡劲,内息浑厚纯正,护体御敌周身不侵" },
  [159] = { name="段氏心法", type="内功", weapon="", desc="大理段氏家传内功,以纯阳温厚为宗,内息平和中正,与一阳指、六脉神剑相辅相成" },
  [160] = { name="天山六阳掌", type="拳脚", weapon="", desc="逍遥派绝学,掌法凝纯阳之气,变化精微奥妙,掌力所至如六月骄阳灼人,为天山童姥一脉的看家本领" },
  [161] = { name="九歌神刀流", type="刀法", weapon="刀", desc="宋缺以《九歌》诸神为刀、《天问》之辞为招,九式环环相扣,一刀既出如大江东去、势不可挡" },
  [162] = { name="武器切换", type="其他", weapon="", desc="临敌时随手换刃: 回合开始以武功等级% 的概率从所携兵刃中另换一柄(不与手中这柄相同)再战, 不占用本回合; 各柄兵刃机会均等, 伤害随新兵刃攻击力重算" },
  [163] = { name="壁虎游墙功", type="轻功", weapon="", desc="江湖奇门轻功,身法紧凑如壁虎附墙,贴壁游走、缘壁而上,于窄壁绝壁间进退自如" },
  [164] = { name="慕容心法", type="内功", weapon="", desc="姑苏慕容氏家传心法,以斗转星移之理运化内息,借力归元、以彼之道还施彼身,内息圆转不滞" },
  [165] = { name="嵩阳神掌", type="拳脚", weapon="", desc="嵩山派镇派掌法,掌势雄浑如中岳巍峨,大开大合正大刚猛,为嵩山掌门一脉绝学" },
  [166] = { name="嵩山剑法", type="剑法", weapon="剑", desc="嵩山派十七路剑法,剑走中正气象森严,如中岳群峰连绵相属,守御绵密而攻伐凌厉" },
  [167] = { name="血海魔功", type="内功", weapon="", desc="血刀门不传之秘,以杀生之血淬炼真气,内力浑厚中透着森然血气,愈战愈狂如血海翻涌" },
  [168] = { name="百花错拳", type="拳脚", weapon="", desc="天池怪侠袁士霄所创奇门拳法,招式似是而非、错中有正,看去处处破绽实则杀机暗藏,令人防不胜防" },
  [169] = { name="金刚伏虎刀", type="刀法", weapon="刀", desc="少林一路刚猛刀法,刀势沉雄如金刚怒目,一刀既出伏虎降龙,以力破巧以刚制柔" },
  [170] = { name="华山混元功", type="内功", weapon="", desc="华山派正宗内功,以混元一气为宗,内息浑厚圆转、刚柔并济,为华山剑法之根基" },
  [171] = { name="追魂夺命剑", type="剑法", weapon="剑", desc="红花会无尘道人成名剑法,断臂之后以单臂运剑,剑走轻灵迅疾、招招追魂夺命,一剑既出连绵不绝" },
  [172] = { name="连环迷踪腿", type="拳脚", weapon="", desc="无尘道人断臂后苦练的腿上功夫,腿法连环、步伐迷踪,虚虚实实腿影重重,令人难辨来路" },
  [173] = { name="无影神拳", type="拳脚", weapon="", desc="拳法迅疾无伦,出拳不见形影、只闻风声,敌人未及察觉已然中拳,故名无影神拳" },
  [174] = { name="菊花剑法", type="剑法", weapon="剑", desc="剑法清绝如秋菊傲霜,剑走轻灵、招招含霜带露,于萧瑟秋意中暗藏凌厉杀机" },
  [175] = { name="天罡归元气", type="内功", weapon="", desc="昆仑派玄门内功,采天罡北斗之气归元固本,内息精纯悠长,运转如北斗周转生生不息" },
  [176] = { name="迅雷剑法", type="剑法", weapon="剑", desc="昆仑剑法,剑势迅疾如雷、快不可挡,一剑既出连绵如闪电,令人不及掩耳" },
  [177] = { name="天罡破虚指", type="拳脚", weapon="", desc="昆仑指法,指劲凌厉如天罡星芒,隔空点穴破虚而入,指到之处劲气洞穿,无坚不摧" },
  [178] = { name="灵鳌步", type="轻功", weapon="", desc="桃花岛轻功,步法沉稳健捷如灵鳌负山,看似从容闲雅实则迅疾无伦,踏波履浪如履平地" },
  [179] = { name="玉女心经", type="内功", weapon="", desc="古墓派镇派内功,林朝英所创,须两人分修阴阳、互通互补方得大成,内息清灵冷澈、柔中带韧" },
  [180] = { name="天罗地网", type="轻功", weapon="", desc="古墓派轻功,身法绵密如天罗地网,进退趋避无隙可乘,纵是强敌环伺亦难近身" },
  [181] = { name="美女拳法", type="拳脚", weapon="", desc="古墓派拳法,招招取美女之姿,举手投足如舞如媚,柔中藏刚、美里含杀,令人心神摇曳间已中拳" },
  [182] = { name="天山掌法", type="拳脚", weapon="", desc="天山派掌法,掌走轻灵而又沉雄,如天山峰顶风云变幻,看似飘忽实含千钧之力,正奇相生" },
  [183] = { name="天山剑法", type="剑法", weapon="剑", desc="天山派十七路剑法,剑势雄奇,如天山横绝西域绵延万里,一剑既出气象万千,兼具轻灵与沉雄" },
  [184] = { name="长生诀", type="内功", weapon="", desc="上古奇书所载养生玄功,导引吐纳以求长生,内息绵柔悠长如春水不绝,看似平和却蕴含无穷生机" },
  [185] = { name="玄冥神掌", type="拳脚", weapon="", desc="百损道人所创阴毒掌法,掌力阴寒彻骨,中掌者寒毒入髓、生机日消,唯纯阳内力可解" },
  [186] = { name="幻阴指", type="拳脚", weapon="", desc="成昆绝技,指劲阴毒诡谲,隔空点出阴寒指气,中者经脉如被阴气噬咬,伤于无形" },
  [187] = { name="灵犀一指", type="拳脚", weapon="", desc="陆小凤成名绝技,两指一夹便可夹住天下任何兵刃暗器,指力灵巧通玄,以巧破力、以静制动" },
  [188] = { name="凤舞九天", type="轻功", weapon="", desc="陆小凤轻功身法,翩然如凤翔九天,腾挪转折轻灵飘逸,纵是绝境亦能从容遁去" },
  [189] = { name="万流归宗", type="内功", weapon="", desc="博大精深的内家心法,万流归宗、诸法归一,纳百般真气于一炉,内息浑厚绵长而圆融无滞" },
  [190] = { name="伏虎拳", type="拳脚", weapon="", desc="刚猛外家拳法,拳势雄浑如伏虎降龙,一拳既出力可开碑,以刚猛见长" },
  [191] = { name="小李飞刀", type="刀法", weapon="刀", desc="李寻欢一脉绝技,刀出如电、例不虚发,一刀既出便已定生死,刀在人在、刀亡人亡" },
  [192] = { name="嫁衣神功", type="内功", weapon="", desc="武林异人燕南天所传无上内功,纯阳刚猛、浑厚无比,练成后真气如熔金灼铁,为天下至刚至阳之属" },
  [193] = { name="大旗风云掌", type="拳脚", weapon="", desc="大旗门镇门掌法,掌势如大旗猎猎、风云变色,雄浑浩荡气象万千,一掌拍出如千军万马齐至" },
  [194] = { name="铁血十二式", type="剑法", weapon="剑", desc="大旗门镇门剑法,十二式一气呵成,剑势刚烈如铁、凌厉见血,剑出如虹气势无前" },
  [195] = { name="削香剑法", type="剑法", weapon="剑", desc="剑法阴柔诡谲,剑走轻灵、招招削向要害,如刀削花枝般无声无息,美中藏杀令人防不胜防" },
  [196] = { name="少林九阳功", type="内功", weapon="", desc="少林高僧自九阳真经中悟出的内功,刚阳浑厚、生生不息,为少林一脉至阳护体之根基" },
  [197] = { name="龙爪手", type="拳脚", weapon="", desc="少林七十二绝技之一,五指运劲如龙爪攫物,刚猛凌厉而又变化精微,抓拿擒锁无所不能" },
  [198] = { name="蛤蟆功", type="内功", weapon="", desc="白驼山镇山绝学,蓄势如蛤蟆蹲踞、发劲如雷霆万钧,内力愈蓄愈厚,一发不可收拾" },
  [199] = { name="灵蛇杖法", type="杖法", weapon="杖", desc="白驼山独门杖法,杖走灵蛇之势,忽曲忽直、蜿蜒莫测,杖端吐吞如灵蛇吐信,诡异狠辣防不胜防" },
  [200] = { name="奇门八卦", type="内功", weapon="", desc="桃花岛主自创内功,以奇门八卦之理运转真气,内息变化万端、玄妙莫测,五行相生循环不竭" },
  [201] = { name="落英神剑掌", type="拳脚", weapon="", desc="桃花岛绝学,掌法取落英缤纷之意,掌影纷飞如花瓣散落,潇洒飘逸中暗藏森然剑意,虚实相生令人难辨" },
  [202] = { name="玉箫剑法", type="剑法", weapon="剑", desc="桃花岛镇岛剑法,以玉箫代剑,剑走轻灵潇洒、变化奇诡,如箫音悠扬连绵不绝,雅致之中暗藏杀机" },
  [203] = { name="小无相功", type="内功", weapon="", desc="逍遥派无上内功,不着形相、无迹可寻,能模仿天下诸般武功而威力犹有过之,内息精微玄妙变化无穷" },
  [204] = { name="袈裟伏魔功", type="内功", weapon="", desc="少林上乘内功,内息浑厚如渊、正气浩然,可伏魔降妖、御外邪侵体,为护体伏魔的根本功夫" },
  [205] = { name="般若掌", type="拳脚", weapon="", desc="少林七十二绝技之一,掌法取般若智慧之意,掌势沉雄庄严、刚柔相济,一掌拍出如金刚降魔" },
  [206] = { name="伏魔杖法", type="杖法", weapon="杖", desc="少林七十二绝技之一,杖法沉雄刚猛,一杖扫出如金刚降魔,以正大光明之势伏一切魔障" },
  [207] = { name="修罗阴煞功", type="内功", weapon="", desc="梁羽生笔下邪派无上内功,阴煞之气森然彻骨,运功时煞气环绕、阴风扑面,中者气血为之凝滞" },
  [208] = { name="天罗步法", type="轻功", weapon="", desc="诡异身法,步走天罗之势,左旋右转、虚实莫测,如入天罗地网令人无从捉摸" },
  [209] = { name="衡山剑法", type="剑法", weapon="剑", desc="衡山派剑法,剑走飘逸,如潇湘夜雨绵绵不绝,一柄长剑藏于胡琴之中,出手迅捷如电" },
  [210] = { name="恒山剑法", type="剑法", weapon="剑", desc="恒山派剑法,守御绵密如磐石不移,剑势柔中带韧,绵里藏针后发制人" },
  [211] = { name="昆仑剑法", type="剑法", weapon="剑", desc="昆仑派剑法,剑势雄奇如昆仑横绝,大开大合兼具轻灵,为西域剑法之宗" },
  [212] = { name="铁剑门剑法", type="剑法", weapon="剑", desc="铁剑门剑法,重剑无锋大巧不工,剑势沉雄朴拙,以拙胜巧以重制轻" },
  [213] = { name="嵩阳铁剑法", type="剑法", weapon="剑", desc="郭嵩阳成名剑法,以嵩阳铁剑运使,剑势磊落孤高,一剑既出便见真章" },
  [214] = { name="不死印法", type="内功", weapon="", desc="魔门无上心法,以不死为意、借力化力,内息诡异莫测,受创愈重其势愈强,几近不死之身" },
  [215] = { name="化骨绵掌", type="拳脚", weapon="", desc="阴毒掌法,掌力柔若无骨绵绵而入,中掌时不觉有异,数日后筋骨渐化、气血俱消,死状诡异" },
  [216] = { name="踏月留香", type="轻功", weapon="", desc="盗帅轻功,踏月而行、过处留香,身法飘逸潇洒如凌波踏月,纵是绝顶高手亦难伤其分毫" },
  [217] = { name="天山轻功", type="轻功", weapon="", desc="天山派轻功,身法高远清绝如天山绝顶之风,腾挪之际轻灵超逸,深得雪域凌虚之妙" },
  [218] = { name="苗家剑法", type="剑法", weapon="剑", desc="苗人凤家传剑法,剑势堂堂正正如金面佛之名,一剑既出光明磊落,与胡家刀法并称当世刀剑双绝" },
  [219] = { name="呆鸡防御", type="其他", weapon="", desc="虽呆若木鸡而守势不乱: 自身处于呆鸡状态时, 回避与招架点数不受呆鸡的降低惩罚(仍无法行动)" },
  [220] = { name="吸星大法", type="其他", weapon="", desc="夺天地之造化,侵日月之玄机: 命中敌人时,按造成的伤害吸取其内力为己用,吸摄的内力可突破自身内力上限(至两倍)" },
  [221] = { name="排云掌", type="拳脚", weapon="", desc="雄霸三大绝学之一, 掌法雄浑如排云推月, 一浪高过一浪. 后传于二弟子步惊云." },
  [222] = { name="风神腿", type="拳脚", weapon="", desc="雄霸三大绝学之一, 腿法轻捷如风, 起落无痕. 后传于三弟子聂风." },
  [223] = { name="三分归元气", type="拳脚", weapon="", desc="雄霸融天霜拳、排云掌、风神腿三家之长而成的绝学, 三分归元, 气象万千, 为天下会镇帮之技." },
  [224] = { name="冰心诀", type="内功", weapon="", desc="聂家祖传内功, 以冰心御血气, 心境越是空明, 内力越是精纯绵长." },
  [225] = { name="摩诃无量", type="内功", weapon="", desc="佛门无上心法, 无量光无量寿之意. 内力浩瀚如海, 绵绵无尽." },
  [226] = { name="云踪魅影", type="轻功", weapon="", desc="来去如云, 倏忽若影, 是极上乘的轻身功夫." },
  [227] = { name="剑影无踪", type="轻功", weapon="", desc="剑客身法, 人随剑走, 剑影所在, 人身已杳." },
  [228] = { name="天霜真气", type="内功", weapon="", desc="雄霸一脉的至寒真气, 功法森冷, 出手时劲力透骨." },
  [229] = { name="蔷薇棘鞭", type="鞭法", weapon="鞭", desc="藏马以妖力催生蔷薇之鞭, 柔韧锋锐俱备, 鞭过之处荆棘丛生." },
  [230] = { name="植物操使", type="拳脚", weapon="", desc="藏马的妖狐之力, 可催动草木藤蔓为其爪牙, 出手无声而杀机四伏." },
  [231] = { name="邪王炎杀拳", type="拳脚", weapon="", desc="飞影自魔界习得的炎系拳法, 拳上带着魔界之火, 中之者灼痛难当." },
  [232] = { name="黑龙波", type="拳脚", weapon="", desc="飞影的压箱绝技: 以自身妖气凝成黑龙之形, 吞噬一切. 威力之强, 连他自己也难以收放自如." },
  [233] = { name="妖怪刚力", type="拳脚", weapon="", desc="户愚吕弟将一身筋肉练至极致, 每一击都是纯粹的力量碾压, 毫无花巧可言." },
  [234] = { name="妖狐变身", type="内功", weapon="", desc="藏马唤醒体内妖狐血脉, 妖力暴涨. 变身之后力量与速度都远非人形可比." },
  [235] = { name="魔界斗气", type="内功", weapon="", desc="飞影以魔界之气淬炼肉身, 斗气愈盛, 出手愈烈." },
  [236] = { name="妖怪肌力", type="内功", weapon="", desc="户愚吕弟的妖化肌肉, 硬度与爆发力都超乎常理, 寻常兵器难伤分毫." },
  [237] = { name="邪眼", type="轻功", weapon="", desc="飞影额上邪眼所具的感知之力, 可洞悉对手气机与破绽. 凭此身法, 先发制人." },
  [238] = { name="妖气缠身", type="轻功", weapon="", desc="妖怪以妖气护体、借妖气疾行. 身形飘忽如烟, 寻常招式难以沾身." },
  [239] = { name="五轮大转", type="刀法", weapon="刀", desc="西域密宗无上绝学, 金银铜铁铅五轮脱手飞旋, 轮转不绝, 如五龙盘空, 令敌无从招架。" },
  [240] = { name="先天破体无形剑气", type="拳脚", weapon="", desc="关七自创的剑气绝学, 号称剑气极致。不需手持兵刃, 剑气可自体内任意部位乃至毛发体表发出, 随手挥洒、无意运聚即可伤人, 终臻驭气之境。" },
  [241] = { name="冲灵剑法", type="剑法", weapon="剑", desc="令狐冲与岳灵珊少年时在华山同创的剑法, 招式出自二人玉女峰同游的旧事, 看似儿戏, 却因朝夕相处、心意相通而别有精妙, 剑势轻灵缠绵。" },
  [242] = { name="灵剑", type="拳脚", weapon="", desc="桑原和真以灵力凝成的光之剑. 少年心性的一腔热血尽数化作剑上锋芒, 越是危急越是锐利." },
  [243] = { name="灵光波动拳", type="拳脚", weapon="", desc="幻海一脉相承的灵光波动拳. 灵光自掌心生, 化作波动层层扩散, 刚柔并济." },
  [244] = { name="灵力觉醒", type="拳脚", weapon="", desc="萤子在一次次危难中觉醒的灵力. 力量谈不上精纯, 那份不肯退让的心意却比什么都实在." },
  [245] = { name="灵气疾行", type="轻功", weapon="", desc="桑原将灵力灌入双腿, 一步踏出便有开碑裂石之势. 虽不精巧, 却快得毫无道理." },
  [246] = { name="热血斗志", type="内功", weapon="", desc="桑原凭着一股不服输的劲头激荡灵力, 越是苦战, 灵力反倒越是旺盛." },
  [247] = { name="灵光身法", type="轻功", weapon="", desc="幻海以灵光御身, 身形明灭不定. 看似未动, 实则早已换了方位." },
  [248] = { name="灵光波动功", type="内功", weapon="", desc="幻海修习一生的灵光波动功. 灵力充盈周身, 举手投足间自有灵光相随." },
  [249] = { name="灵巧身法", type="轻功", weapon="", desc="萤子身形轻盈, 闪避全凭一股机敏. 没有花巧的步法, 却总能在紧要关头让开." },
  [250] = { name="坚韧之心", type="内功", weapon="", desc="萤子虽不谙武艺, 却有一颗比谁都坚韧的心. 心有牵挂, 灵力便生生不息." },
  [251] = { name="左右互搏", type="其他", weapon="", desc="一心二用、双手各司其职的奇术: 练功时事半功倍, 步进 ×(1+等级/100)², 等级越高进境越快" },
  [252] = { name="运气调息", type="其他", weapon="", desc="吐纳导引、调匀气息的法门: 打坐时内息运转更疾, 步进 ×(1+等级/100)², 等级越高回气越快" },
}
D.NPC = {
  [0] = { name="NONE!!", pai="0", hp=0, maxhp=0, dmg=0, def=0, exp=0, force=0, msg="NONE!!" },
  [1] = { name="潘小莲", pai="255", hp=370, maxhp=370, dmg=0, def=0, exp=5000, force=0, msg="潘小莲开了家豆腐店,别看她年过三十可风韵犹存,不少人想吃她的豆腐呢." },
  [2] = { name="小顽童", pai="0", hp=100, maxhp=100, dmg=0, def=0, exp=10, force=0, msg="小顽童蹦蹦跳跳的,一副兴高采烈的样子." },
  [3] = { name="捕快", pai="0", hp=370, maxhp=370, dmg=0, def=0, exp=20000, force=0, msg="六扇门里的捕快,虽然武艺平平,可为人正直,名声不错." },
  [4] = { name="采花大盗", pai="0", hp=320, maxhp=320, dmg=0, def=50, exp=105000, force=0, msg="采花大盗一直被官府通缉,但他仗着轻功超群,一直逍遥法外." },
  [5] = { name="厨师", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=10000, force=0, msg="这是一个胖胖的的厨师." },
  [6] = { name="村长", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=40000, force=0, msg="作为一村之长，村长总是从忙忙碌碌" },
  [7] = { name="独行大侠", pai="254", hp=620, maxhp=620, dmg=0, def=50, exp=160000, force=1, msg="独行大侠刻苦钻研天下武艺,武功不知是何来路,当年为追踪碧眼狐狸一路到此,没想到就此在小镇住了下来." },
  [8] = { name="独脚大盗", pai="0", hp=320, maxhp=320, dmg=0, def=50, exp=80000, force=0, msg="这是一个江洋大盗,年轻时被官兵砍断了一条腿,后来到平一指那里装了一条木腿,身法还算灵活." },
  [9] = { name="卖花妞", pai="255", hp=160, maxhp=160, dmg=0, def=0, exp=10000, force=0, msg="美丽的卖花姑娘正在细心的用园工剪修剪花枝." },
  [10] = { name="中年妇人", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=6000, force=0, msg="这是个胖胖的中年女子,头发乱蓬蓬的,脸上老挂着笑容.她是出了名的马大哈,经常丢三落四,整天不是不见了这就是找不到那." },
  [11] = { name="葛朗台", pai="255", hp=320, maxhp=320, dmg=0, def=0, exp=110000, force=0, msg="这是小镇当铺的老板,一生吝啬小气,别看他家财万贯,身上却从来没几个铜板." },
  [12] = { name="道德和尚", pai="0", hp=100, maxhp=100, dmg=0, def=0, exp=10, force=0, msg="慈眉善目的得道高僧,似乎从来没有烦恼." },
  [13] = { name="西门广", pai="0", hp=220, maxhp=220, dmg=0, def=0, exp=1000, force=0, msg="一个有钱人家的公子哥,手里拿着一把扇子正在闲逛." },
  [14] = { name="石料管事", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=30000, force=0, msg="石料厂管事负责管理工地的石料,小镇最近要翻修,急需石料,开采出来不少可人手不足,石料厂管事为此事也着实头疼." },
  [15] = { name="工地管事", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=30000, force=0, msg="工地管事负责准备石料,可目前人手不够,石料在石料厂堆了不少可就是运不过来." },
  [16] = { name="官兵", pai="0", hp=320, maxhp=320, dmg=0, def=30, exp=55000, force=0, msg="这是个正在这里站岗的守城官兵" },
  [17] = { name="神秘人", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=400, force=0, msg="不知从哪里来的游玩客人,小镇虽然风景平淡,他却饶有兴味." },
  [18] = { name="黑衣大盗", pai="0", hp=320, maxhp=320, dmg=0, def=15, exp=160000, force=0, msg="黑衣大盗一身黑衣,脸上也用黑布面罩蒙起来,没人知道他是什么来路,好象也没怎么为难乡亲们." },
  [19] = { name="何铁手", pai="255", hp=570, maxhp=570, dmg=0, def=0, exp=110000, force=1, msg="何铁手原是五毒教的首脑,后师承袁程志赐名何锡守.她美貌如花,看不出多大年纪,左手齐腕装了个铁钩,锋利无比,铁手之名即源于此." },
  [20] = { name="荷西", pai="255", hp=320, maxhp=320, dmg=0, def=0, exp=8000, force=0, msg="荷西是个外乡人,到小镇安家也有好长时间了,大家也慢慢将他作本地人看了.他开个渔具店,自己钓鱼,收购鱼,还花钱到馆子里吃自己钓的鱼,真是怪人." },
  [21] = { name="流氓", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=5000, force=0, msg="一个满脸横肉的小流氓,一副寻衅滋事的架式." },
  [22] = { name="流氓头", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=35000, force=0, msg="这是当地的流氓头领,附近的小流氓都听他的指挥." },
  [23] = { name="茅十七", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=35000, force=0, msg="茅十七是茅十八的哥哥,自从十八随韦小宝进京后就没回来,这不他一路找到小镇来了." },
  [24] = { name="李也白", pai="0", hp=395, maxhp=395, dmg=0, def=0, exp=40000, force=3, msg="放浪不羁的吟游诗人,听说剑法很不错." },
  [25] = { name="老婆婆", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=5000, force=0, msg="老婆婆满脸皱纹,在这个镇里生活了几十年了,大家都叫她婆婆." },
  [26] = { name="平一指", pai="255", hp=320, maxhp=320, dmg=0, def=30, exp=60000, force=0, msg="此人又矮又胖,头大无比,两撇鼠须甚是滑稽.可谁知道他就是医术高超的「杀人神医」平一指.可是他性格古怪,不是什么人都医的." },
  [27] = { name="小商贩", pai="255", hp=320, maxhp=320, dmg=0, def=0, exp=6000, force=0, msg="面目和蔼的小贩,推车上插了个草靶,上面零落地插了些糖葫芦." },
  [28] = { name="小书童", pai="0", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一个替顾炎武倒茶磨墨的书童,青衣小帽,一脸稚气中透出顽皮." },
  [29] = { name="小裁缝", pai="255", hp=140, maxhp=140, dmg=0, def=0, exp=200, force=0, msg="一位小裁缝,正在学习缝制衣服." },
  [30] = { name="老裁缝", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=10000, force=0, msg="老裁缝的手脚甚是麻利,显然已做了多年了." },
  [31] = { name="顾炎武", pai="254", hp=620, maxhp=620, dmg=0, def=0, exp=2000000, force=1, msg="顾炎武是个博学多闻的宿儒,提到他的学问乡亲门都佩服得无体投地.因为不满时政,他隐居于此,开了间私塾聊以度日." },
  [32] = { name="挑夫", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=500, force=0, msg="一位专门挑运行李的挑夫,随身带着扁担绳子,人们称他们\"棒棒军\"." },
  [33] = { name="民团团丁", pai="0", hp=370, maxhp=370, dmg=0, def=0, exp=12000, force=0, msg="负责小镇治安的团丁,身材高大,看上去非常结实." },
  [34] = { name="胡屠户", pai="255", hp=320, maxhp=320, dmg=0, def=0, exp=12000, force=0, msg="你看到一个剽悍的大块头,正在用钢刀剔猪肉." },
  [35] = { name="店小二", pai="255", hp=180, maxhp=180, dmg=0, def=0, exp=300, force=0, msg="这位店小二正笑咪咪地忙着,还不时拿起挂在脖子上的抹布擦脸." },
  [36] = { name="寻捕", pai="0", hp=420, maxhp=420, dmg=0, def=30, exp=60000, force=1, msg="寻捕大人在这一带颇有声望,破了不少案子,虽然不能和江湖上的四大名捕相提并论,可也是名声显赫." },
  [37] = { name="盐商", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=10000, force=0, msg="自古以来贩私盐就是违法的,可这个盐商不知打通了什么关节,居然大模大样招摇过市." },
  [38] = { name="杂货贩", pai="255", hp=320, maxhp=320, dmg=0, def=0, exp=30000, force=0, msg="卖杂货的是个年轻汉子,面带微笑." },
  [39] = { name="商宝震", pai="1", hp=470, maxhp=470, dmg=0, def=0, exp=60000, force=10, msg="商宝震是商剑鸣大儿子,刀法掌法也得过父亲的真传." },
  [40] = { name="武师教头", pai="0", hp=420, maxhp=420, dmg=0, def=0, exp=40000, force=4, msg="他是护院武师的总教头,在八卦掌上也下了多年的苦功夫,虽算不上高手,对付一般江湖人物也游刃有余了." },
  [41] = { name="马春花", pai="0", hp=355, maxhp=355, dmg=0, def=0, exp=20000, force=0, msg="马春花是马行空的女儿,一张圆圆的鹅蛋脸,眼珠子黑漆漆的,两颊晕红,周身透着一股青春活泼的气息." },
  [42] = { name="护院武师", pai="0", hp=395, maxhp=395, dmg=0, def=0, exp=15000, force=0, msg="一个高大结实的武师,据说是从沧州来的,武艺还不错." },
  [43] = { name="王剑杰", pai="0", hp=570, maxhp=570, dmg=0, def=30, exp=140000, force=2, msg="王剑杰一张紫膛脸,神态威猛,身材魁梧,他是王维扬的二儿子,武学造诣也是不凡." },
  [44] = { name="商剑鸣", pai="1", hp=570, maxhp=570, dmg=0, def=0, exp=180000, force=2, msg="商剑鸣是威震河朔王维扬的大弟子,他在本门八卦刀法上浸润多年,造诣煞是不凡,从他的外号就可看出武林中对他的刀法也很推崇." },
  [45] = { name="王剑英", pai="0", hp=620, maxhp=620, dmg=0, def=40, exp=180000, force=10, msg="王剑英是王维扬的大儿子,自小随父亲练功,八卦门的不传绝学\"八阵八卦掌\"也尽数传给了他" },
  [46] = { name="商老太", pai="0", hp=470, maxhp=470, dmg=0, def=0, exp=80000, force=10, msg="商老太幼时陪伴父亲、婚后跟随丈夫闯荡江湖,也会过无数武林豪杰,平时却是深藏不露." },
  [47] = { name="平阿四", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=1000, force=0, msg="平阿四只余左臂,一条极长的刀疤从右眉起斜过鼻子,一直延伸到左边嘴角,显得极是可怖." },
  [48] = { name="王维扬", pai="1", hp=670, maxhp=670, dmg=0, def=0, exp=800000, force=12, msg="王维扬是北京震远镖局总标头,当年凭一对八卦掌,一把八卦刀威震江湖绿林.黑道中有一句话道：宁碰阎王，莫碰老王，端的是名扬天下" },
  [49] = { name="马行空", pai="0", hp=520, maxhp=520, dmg=0, def=40, exp=110000, force=2, msg="马行空身高不过五尺,但目光炯炯,凛然有威.自从上次押镖经过商家堡,这一住就住了下来." },
  [50] = { name="徐铮", pai="0", hp=395, maxhp=395, dmg=0, def=0, exp=35000, force=0, msg="他是马行空的弟子,生得浓眉大眼,神情粗豪,脸上生满紫色小疮,但步履轻健,精神饱满,却也英气勃勃." },
  [51] = { name="阎基", pai="0", hp=445, maxhp=445, dmg=0, def=0, exp=15000, force=2, msg="此人面貌委琐,缩头缩脑,神情打扮,就如是个暴发户富商.他本来是个江湖跌打医生,后来干起了没本的买卖." },
  [52] = { name="庄丁", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=2000, force=0, msg="一个年轻的庄丁,正在左顾右盼,他的职责是防止形迹可疑的人进入庄院." },
  [53] = { name="茶花女", pai="255", hp=280, maxhp=280, dmg=0, def=0, exp=35000, force=0, msg="茶花女是从云南大理来的,她种出的茶花很多都是名品." },
  [54] = { name="公孙大娘", pai="0", hp=620, maxhp=620, dmg=0, def=0, exp=150000, force=0, msg="公孙大娘的\"剑器之舞\"名动京城,昔年老杜一观后曾发出\"剑器一舞动四方\"的赞叹.岂知此舞实应为武,没有高深的武功又怎能舞出绝世的剑器呢." },
  [55] = { name="红拂女", pai="0", hp=540, maxhp=540, dmg=0, def=0, exp=140000, force=1, msg="红拂女长发及膝,当年虬髯客也曾被她梳理长发的容光所吸引.没想到这多年后她还是如此年轻,看来李靖得仙丹的传说可能真有其事." },
  [56] = { name="绿珠", pai="0", hp=550, maxhp=550, dmg=0, def=0, exp=120000, force=2, msg="绿珠是个容貌出色的美女,气节刚烈的她坠楼后并没有死,李青照救她到此并传了她高深的武功.虽经平一指的精心调治,她的腿还是留下了残疾." },
  [57] = { name="平婆婆", pai="2", hp=420, maxhp=420, dmg=0, def=0, exp=60000, force=0, msg="平婆婆是李青照的奶母,多年来一直跟随左右,耳闻目睹间竟然也修习了一身不错的武功.现在花间派的新弟子武功修习由她指导." },
  [58] = { name="桑轻虹", pai="2", hp=570, maxhp=570, dmg=0, def=0, exp=160000, force=0, msg="桑轻虹是李青照的嫡传弟子,她年纪比唐晚词尚小几岁,可却得了花间派花团锦簇鞭法的真传." },
  [59] = { name="李青照", pai="2", hp=670, maxhp=670, dmg=0, def=0, exp=1000000, force=2, msg="李青照温文尔雅,仪态万方.她不但武艺绝伦并且精于词律,她的诗词广为传诵.据说花间派的绝技一剪梅花手就是她于一首词中演化而来." },
  [60] = { name="入画", pai="0", hp=335, maxhp=335, dmg=0, def=0, exp=40000, force=10, msg="入画是李青照身边的侍女中容貌最出色的一个,她开朗好动,笑语嫣然,狂而不损其媚人皆乐之." },
  [61] = { name="瑞婆婆", pai="0", hp=395, maxhp=395, dmg=0, def=0, exp=35000, force=0, msg="瑞婆婆是李青照身边的老佣人,她和平婆婆一起服侍李青照,关系很是亲密.她比平婆婆还小上几岁,身体十分硬朗." },
  [62] = { name="柳如是", pai="0", hp=495, maxhp=495, dmg=0, def=40, exp=65000, force=20, msg="柳如是是京城的名妓,江湖传言她是青龙会的红旗老吆,不过看她娇娇弱弱的样子谁也想不到她身怀武功." },
  [63] = { name="李师师", pai="0", hp=320, maxhp=320, dmg=0, def=40, exp=65000, force=0, msg="李师师是京城的名妓,可很少有人知道她是\"红鞋子\"组织的秘密成员,更没人知道她还有一身花间派的武功." },
  [64] = { name="侍书", pai="0", hp=335, maxhp=335, dmg=0, def=0, exp=40000, force=10, msg="侍书是李青照身边的侍女,她年纪大上几岁,行为端庄不苟言笑." },
  [65] = { name="司棋", pai="0", hp=180, maxhp=180, dmg=0, def=0, exp=3000, force=0, msg="司棋是李青照身边的侍女,一副天真烂漫的样子." },
  [66] = { name="听琴", pai="0", hp=180, maxhp=180, dmg=0, def=0, exp=3000, force=0, msg="听琴是李青照身边的侍女,一副天真烂漫的样子." },
  [67] = { name="唐晚词", pai="2", hp=570, maxhp=570, dmg=0, def=0, exp=150000, force=0, msg="唐晚词是李青照的嫡传弟子,别看她巧笑如花,但双眸流转间透出一股英气." },
  [68] = { name="小红", pai="0", hp=240, maxhp=240, dmg=0, def=30, exp=45000, force=0, msg="小红原来的名字是什么大家都不记得了,她神色间有时闪过一丝凄苦,经常会凝望窗外发呆." },
  [69] = { name="薛涛", pai="0", hp=550, maxhp=550, dmg=0, def=0, exp=120000, force=2, msg="薛涛素有才名,她制作的信笺被时人称为\"薛涛笺\",她与李青照素有诗书往来,用的都是这种\"薛涛笺\" ." },
  [70] = { name="聂隐娘", pai="0", hp=620, maxhp=620, dmg=0, def=0, exp=180000, force=0, msg="聂隐娘是个传奇人物,她师承空空儿,轻功奇高,以至后来被神化为剑仙一流.她是李青照的闺中密友,两人过从甚密." },
  [71] = { name="白衣教众", pai="0", hp=407, maxhp=407, dmg=0, def=0, exp=30000, force=20, msg="红莲教教众按武功高低依次分为红 白 黑 蓝四色教众." },
  [72] = { name="王璁儿", pai="0", hp=570, maxhp=570, dmg=0, def=0, exp=180000, force=50, msg="红莲教护法,与唐思儿并称 \"红莲双娇\" .其实论到武功,除了教主就数她了." },
  [73] = { name="褚红灯", pai="0", hp=570, maxhp=570, dmg=0, def=0, exp=145000, force=60, msg="一个红脸怒相的大汉,身高足有一丈,站在那里威风凛凛." },
  [74] = { name="方长老", pai="3", hp=570, maxhp=570, dmg=0, def=0, exp=300000, force=12, msg="方长老是红莲教的光明护法,也是戒律堂的执行长老,有违背红莲教义的弟子他从来不会手下留情." },
  [75] = { name="韩长老", pai="0", hp=470, maxhp=470, dmg=0, def=0, exp=140000, force=20, msg="韩长老原在朝廷为官,后不满官场黑暗,遂加入红莲教" },
  [76] = { name="黑衣教众", pai="0", hp=395, maxhp=395, dmg=0, def=0, exp=15000, force=20, msg="红莲教教众按武功高低依次分为红 白 黑 蓝四色教众." },
  [77] = { name="红衣教众", pai="0", hp=420, maxhp=420, dmg=0, def=0, exp=40000, force=20, msg="红莲教教众按武功高低依次分为红 白 黑 蓝四色教众." },
  [78] = { name="蓝衣教众", pai="0", hp=395, maxhp=395, dmg=0, def=0, exp=15000, force=20, msg="红莲教教众按武功高低依次分为红 白 黑 蓝四色教众." },
  [79] = { name="齐林天", pai="0", hp=520, maxhp=520, dmg=0, def=0, exp=90000, force=50, msg="一个白衣白净面皮的中年人,死白的脸上看不出任何喜怒哀乐." },
  [80] = { name="唐思儿", pai="0", hp=420, maxhp=420, dmg=0, def=0, exp=180000, force=40, msg="一代巾帼英雄,人称花木兰第二．" },
  [81] = { name="余鸿儒", pai="3", hp=720, maxhp=720, dmg=0, def=0, exp=900000, force=2, msg="红莲教的教主.红莲教虽是秘密组织,行动诡秘,但一直以扶危济困为宗旨,在老百姓中口碑不错,进年来更是门徒广大,俨然为武林第一大帮会." },
  [82] = { name="十兵卫", pai="0", hp=645, maxhp=645, dmg=0, def=0, exp=160000, force=20, msg="十兵卫是两刀流的创始人,对尹贺一派的一刀流技法一直心存成见.这次他专门来拜访和仲阳,没想到却对一刀流着了迷." },
  [83] = { name="大熊", pai="0", hp=315, maxhp=315, dmg=0, def=0, exp=30000, force=0, msg="大熊是花十郎的弟子,他是个大块头儿,看上去有把子力气,可总有些呆头呆脑." },
  [84] = { name="未知火舞", pai="0", hp=565, maxhp=565, dmg=0, def=0, exp=130000, force=0, msg="未知火舞是不知火流的传人,为迎接下一届格斗之王的邀请赛,专门来拜访和仲阳,学习尹贺一派的技击之法." },
  [85] = { name="浪人甲", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=20000, force=0, msg="这是一个来自远方的浪人,满身征尘,是专门来花讽院朝拜的." },
  [86] = { name="浪人乙", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=45000, force=0, msg="这个浪人来自遥远的北方,他是带着贵重的礼物来拜访和仲阳的." },
  [87] = { name="大口木子", pai="0", hp=335, maxhp=335, dmg=0, def=0, exp=35000, force=0, msg="大口木子是藤王丸的弟子,她是个很静的女子,可学武几年来一直无法领会师傅的高深武功,不过她好象也意不在此." },
  [88] = { name="陈美娜", pai="4", hp=570, maxhp=570, dmg=0, def=0, exp=100000, force=10, msg="陈美娜满脸唳气,一副桀傲不训的神色.她是和仲阳的得意弟子之一,专修一刀流刀法." },
  [89] = { name="孙悟菜", pai="0", hp=500, maxhp=500, dmg=0, def=40, exp=85000, force=0, msg="孙悟菜是龟仙人介绍来的,为下一年的比武大会开开眼界.经花十郎指点后对尹贺派的武功颇有领悟.藤王丸甚至将自己的宝刀河豚毒借给他使用." },
  [90] = { name="食野太郎", pai="0", hp=220, maxhp=220, dmg=0, def=0, exp=15000, force=0, msg="食野太郎人如其名,块头不大可饭量惊人,总是一副受虐待吃不饱的可怜像.他的师傅藤王丸也拿他没办法." },
  [91] = { name="藤王丸", pai="4", hp=570, maxhp=570, dmg=0, def=0, exp=100000, force=10, msg="藤王丸一头乱蓬蓬的长发,脸孔棱角分明,一身风尘骠悍之色.他是和仲阳的得意弟子之一,最爱游历山川." },
  [92] = { name="天津虾", pai="0", hp=500, maxhp=500, dmg=0, def=0, exp=85000, force=10, msg="天津虾是经龟仙人介绍来的,为下一年的比武大会长长见识.经藤王丸的指点后对尹贺一派的武功颇有所领悟." },
  [93] = { name="野比", pai="0", hp=220, maxhp=220, dmg=0, def=0, exp=15000, force=0, msg="野比是花十郎的弟子,他身材瘦小目光闪烁,看来十分顽皮." },
  [94] = { name="枳右京", pai="0", hp=595, maxhp=595, dmg=0, def=0, exp=160000, force=0, msg="藤王丸的好朋友和永远的竞争对手,他患有肺病,走遍世界只为找寻一朵美丽之花送给心爱的人.藤王丸听说平一指刀圭如神,硬把他拖来碰碰运气." },
  [95] = { name="和仲阳", pai="4", hp=695, maxhp=695, dmg=0, def=0, exp=1000000, force=2, msg="和仲阳是个瘦小枯干的小老头,在硕大的竹斗笠下总是一副庸懒的面容.谁也想不到他却是花讽院的院主,尹贺一派的掌门人,弟子遍布天下." },
  [96] = { name="采药道人", pai="0", hp=620, maxhp=620, dmg=0, def=0, exp=85000, force=80, msg="采药道人与清虚道长实是半师半友,也是太极门内外总管．因其少年时降魔无数,人称「小天师」．" },
  [97] = { name="苍月道长", pai="5", hp=570, maxhp=570, dmg=0, def=0, exp=160000, force=0, msg="清虚道长的师弟.三清观声名显赫,他与清虚道长古松道长并称,武林中人提起都是竖起拇指,不但佩服他们武学修为了得,也因他们侠风亮节,武德高尚." },
  [98] = { name="古松道长", pai="5", hp=520, maxhp=520, dmg=0, def=0, exp=160000, force=10, msg="清虚道长的师弟.三清观声名显赫,他与清虚道长苍月道长并称,武林中人提起都是竖起拇指,不但佩服他们武学修为了得,也因他们侠风亮节,武德高尚." },
  [99] = { name="谷虚道长", pai="0", hp=520, maxhp=520, dmg=0, def=0, exp=130000, force=10, msg="一个相貌堂堂的道士．" },
  [100] = { name="明月", pai="0", hp=335, maxhp=335, dmg=0, def=0, exp=40000, force=2, msg="一个胖乎乎的道士,正傻呵呵的不知笑什么．" },
  [101] = { name="清风", pai="0", hp=335, maxhp=335, dmg=0, def=0, exp=15000, force=10, msg="太极门第三代弟子中的杰出人物．" },
  [102] = { name="清虚道长", pai="5", hp=745, maxhp=745, dmg=0, def=0, exp=1100000, force=1, msg="清虚道长面目慈祥,虽年过花甲但鹤发童颜精神矍铄,因常修道家养生之道,为人中正平和深受武林人士爱戴." },
  [103] = { name="烧饭道童", pai="0", hp=200, maxhp=200, dmg=0, def=0, exp=2000, force=0, msg="一个吃的胖胖的小道士,正在烧火．" },
  [104] = { name="桃花", pai="0", hp=260, maxhp=260, dmg=0, def=0, exp=1000, force=0, msg="清虚道长的远房侄女." },
  [105] = { name="土匪", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=45000, force=0, msg="一个体型魁悟,看起来孔武有力的大个子．正狠巴巴的瞪着你．" },
  [106] = { name="土匪头领", pai="0", hp=395, maxhp=395, dmg=0, def=0, exp=60000, force=20, msg="夏鹏展原是太极门中弟子,因贼性难改,落草作了强盗．使一路太极剑法,手中落云剑阴狠无比．" },
  [107] = { name="进香客", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=1000, force=0, msg="一个虔诚的香客." },
  [108] = { name="迎客道童", pai="0", hp=200, maxhp=200, dmg=0, def=0, exp=40000, force=2, msg="一个瘦瘦的小道士,正傻呵呵的不知笑什么．" },
  [109] = { name="知客道长", pai="0", hp=395, maxhp=395, dmg=0, def=0, exp=70000, force=10, msg="太极门第三代弟子中的杰出人物．虽不是很聪明,但师祖却很看重他．" },
  [110] = { name="阿绣", pai="0", hp=485, maxhp=485, dmg=0, def=0, exp=55000, force=15, msg="史婆婆的贴身丫头." },
  [111] = { name="白瑞德", pai="6", hp=695, maxhp=695, dmg=0, def=0, exp=800000, force=50, msg="威德先生白瑞德身材高大,多年来凭借深厚内力和精微剑法一直独步雪山.雪山派在他的带领下也隐隐然成为西北的宗主大派." },
  [112] = { name="张福来", pai="255", hp=320, maxhp=320, dmg=0, def=0, exp=10000, force=0, msg="张福来是雪山派的厨师,手艺远近闻名." },
  [113] = { name="欧阳千善", pai="0", hp=420, maxhp=420, dmg=0, def=0, exp=25000, force=5, msg="雪山门下有很多巡使.因为外人很少能到这里,谷内的巡使大多武功不高.这位巡使身披白袍,腰跨长剑.白袍当胸绣着一只飞扬欲脱的大鹏鸟." },
  [114] = { name="马千刚", pai="0", hp=475, maxhp=475, dmg=0, def=0, exp=65000, force=35, msg="这位马先生来自遥远的大雪山.乃是白瑞德座下有名的高手之一" },
  [115] = { name="赵千猛", pai="0", hp=475, maxhp=475, dmg=0, def=0, exp=65000, force=10, msg="雪山门下有名的高手之一赵千猛.他远看还不错,走近了才发现他长着长长的一张鸟嘴." },
  [116] = { name="薛千柔", pai="0", hp=280, maxhp=280, dmg=0, def=0, exp=20000, force=5, msg="雪山门下女弟子." },
  [117] = { name="史婆婆", pai="0", hp=570, maxhp=570, dmg=0, def=0, exp=130000, force=60, msg="这位史婆婆是本门的一位前辈. 白瑞德初出道时她出了不少力,后来受邀出任本门护法." },
  [118] = { name="花万红", pai="0", hp=470, maxhp=470, dmg=0, def=0, exp=60000, force=20, msg="雪山二代弟子,平日少言寡语." },
  [119] = { name="封万剑", pai="6", hp=570, maxhp=570, dmg=0, def=0, exp=160000, force=2, msg="封万剑是威德先生的大弟子,一身武功尽得威德先生真传,据说在雪山剑法上的造诣已不在掌门人之之下." },
  [120] = { name="王万轫", pai="0", hp=545, maxhp=545, dmg=0, def=0, exp=75000, force=35, msg="大雪山巡山总管－－神鹰使者,负责四处巡查,八方联络." },
  [121] = { name="齐万翼", pai="0", hp=695, maxhp=695, dmg=0, def=0, exp=110000, force=50, msg="白瑞德座下四护法之一.额头高耸,一看就知道功力深厚." },
  [122] = { name="柯万锺", pai="0", hp=570, maxhp=570, dmg=0, def=0, exp=110000, force=60, msg="柯万锺是有名的大力士.以前在狮驼山做二大王,狮驼山被剿灭后他跟着齐万翼投奔白瑞德,做了护法.生平最怕的是老鼠,看到尖嘴猴腮的人就讨厌." },
  [123] = { name="雪山教头", pai="6", hp=420, maxhp=420, dmg=0, def=0, exp=50000, force=0, msg="这是雪山派的武功教头,负责掌管新进弟子的武功学习,别看他面目和蔼,可督导练功却凶得吓人,雪山弟子都很敬重他." },
  [124] = { name="雪豹", pai="0", hp=420, maxhp=420, dmg=0, def=0, exp=50000, force=0, msg="大雪山独有的猛兽,尤其皮毛甚是珍贵" },
  [125] = { name="我是谁", pai="10", hp=1600, maxhp=1600, dmg=0, def=0, exp=2500000, force=80, msg="???" },
  [126] = { name="东方求败", pai="10", hp=1972, maxhp=1972, dmg=0, def=0, exp=3600000, force=100, msg="???" },
  [127] = { name="道德和尚", pai="10", hp=2500, maxhp=2500, dmg=0, def=0, exp=5000000, force=160, msg="???" },
  [128] = { name="艾里克", pai="0", hp=695, maxhp=695, dmg=0, def=0, exp=1000000, force=20, msg="艾里克是远古的凯尔特人,也是第一批迁居到捷克地区的移民。成为吸血鬼后艾里克一直独自隐居在波希米亚的森林,过着原始人般的生活,所以很自然的加入了兽王派." },
  [129] = { name="巴巴雷恩", pai="0", hp=695, maxhp=695, dmg=0, def=0, exp=1000000, force=20, msg="野蛮人--他是文明边缘的几个部落中的成员.在部落之间不间断的战争中使他能够活下来得益于他那野蛮人的坚定意志和强健的体格. 他能够敏锐地感觉他周围的环境." },
  [130] = { name="北海鳄神", pai="7", hp=520, maxhp=520, dmg=0, def=0, exp=500000, force=20, msg="北海鳄神长著蓬松的头发,长长的胡子,突出的眼眶,看上去很吓人,其实他心地很好,可大家见了他都跑,所以他只能和鳄鱼作朋友." },
  [131] = { name="花佗", pai="7", hp=695, maxhp=695, dmg=0, def=0, exp=60000, force=20, msg="花佗模仿虎、鹿、熊、猿、鸟的动作和姿态,创造了创建了一套五禽戏功法，修习后外融百骸畅，中适一念无；旷然忘所在，心与虚俱空,是全民健身运动的倡导者。现隐居兽王派，作个名誉总管。" },
  [132] = { name="李猎户", pai="0", hp=420, maxhp=420, dmg=0, def=0, exp=2000, force=2, msg="一个看起来精明能干的猎户." },
  [133] = { name="娜可露", pai="7", hp=800, maxhp=800, dmg=0, def=0, exp=2000000, force=20, msg="活泼开朗、纯真善良的少女剑士娜可露露,因为大自然受魔物残害而发出哀嚎,所以集合志同道合之士创立兽王派,并出任第一任掌门,以维护大自然的安宁为目标." },
  [134] = { name="索莱斯", pai="0", hp=620, maxhp=620, dmg=0, def=0, exp=150000, force=20, msg="孤独和隐居的个性使很多人不能理解她， 一些时候她看起来反复无常,但是事实上,她懂得在次序和混乱之间的战斗的真谛,就象在战斗中她和战士一样出色。" },
  [135] = { name="人猿泰山", pai="0", hp=510, maxhp=510, dmg=0, def=0, exp=160000, force=40, msg="在非洲原始森林成了孤儿的婴孩在猿猴家族的照料下长大成人,人类探险和出现打破了他宁静和平和世界,而人类将对猿猴家族的伤害更使他加入野兽派来维护动物的权益." },
  [136] = { name="王猎户", pai="0", hp=420, maxhp=420, dmg=0, def=0, exp=2000, force=2, msg="一个看起来精明能干的猎户." },
  [137] = { name="张猎户", pai="0", hp=420, maxhp=420, dmg=0, def=0, exp=2000, force=2, msg="一个看起来精明能干的猎户." },
  [138] = { name="赵猎户", pai="0", hp=420, maxhp=420, dmg=0, def=0, exp=2000, force=2, msg="一个看起来精明能干的猎户." },
  [139] = { name="葛洪", pai="8", hp=620, maxhp=620, dmg=0, def=0, exp=200000, force=20, msg="东晋道士,喜爱建筑,曾在罗浮山南麓建四庵,南庵即为现在的冲虚观,为人平和,弟子们都爱找他聊天." },
  [140] = { name="华岳", pai="0", hp=370, maxhp=370, dmg=0, def=0, exp=50000, force=20, msg="一个聪明机灵的小道士" },
  [141] = { name="空虚", pai="0", hp=370, maxhp=370, dmg=0, def=0, exp=50000, force=20, msg="一个有点木讷的小道士." },
  [142] = { name="留孙真人", pai="8", hp=820, maxhp=820, dmg=0, def=0, exp=700000, force=20, msg="一个茅山道士,外人传言他能预知未来,可他从来不说什么!" },
  [143] = { name="茅哀", pai="0", hp=945, maxhp=945, dmg=0, def=0, exp=1000000, force=20, msg="茅盈之弟,汉他节四年(公元前66年)拜上都太守,不久转为河西太守.后辞官而去,修习道家之术,于茅盈,茅固并称茅山三圣." },
  [144] = { name="茅固", pai="0", hp=945, maxhp=945, dmg=0, def=0, exp=1000000, force=20, msg="茅盈之弟,在汉景帝时已官至家孝廉,其后一直官运享通,春风得意,后经茅盈施法设盛宴点化,随其兄入山采药,济世救人,并修习道家之术." },
  [145] = { name="茅盈", pai="8", hp=1070, maxhp=1070, dmg=0, def=0, exp=2000000, force=40, msg="茅山派开山祖师,隐居修炼于以奇险厒名天下的西岳华山,秦始皇三十九年(公元前248年)九月庚于日,修成正果,得成大道." },
  [146] = { name="小明月", pai="0", hp=370, maxhp=370, dmg=0, def=0, exp=50000, force=20, msg="一个结实的小道士" },
  [147] = { name="小清风", pai="0", hp=370, maxhp=370, dmg=0, def=0, exp=50000, force=20, msg="一个能干的小道士" },
  [148] = { name="张伯雨", pai="0", hp=670, maxhp=670, dmg=0, def=0, exp=900000, force=20, msg="伯雨是元代时的神仙道教人物,他做道士后更加仰慕齐梁“华阳隐居”陶弘景的风范,因而自号“句曲外史”,名嗣真，字天雨，号贞居子，又名称张雨." },
  [149] = { name="干匠", pai="0", hp=670, maxhp=670, dmg=0, def=0, exp=900000, force=20, msg="他是铸剑师干匠,拥有许多神兵利器" },
  [150] = { name="墨邪", pai="0", hp=500, maxhp=500, dmg=0, def=60, exp=50000, force=30, msg="干匠的妻子,越女剑的传人" },
  [151] = { name="船夫", pai="0", hp=350, maxhp=350, dmg=0, def=0, exp=34995, force=0, msg="平安镇渡口的船夫." },
  [152] = { name="蓝胡子", pai="0", hp=620, maxhp=620, dmg=0, def=0, exp=180000, force=10, msg="银钩赌坊的老板,四方脸上笑意可掬,一双眼睛却深不见底,江湖上没人知道他真正的来历." },
  [153] = { name="丁香姨", pai="0", hp=450, maxhp=450, dmg=0, def=0, exp=80000, force=6, msg="赌坊里迎来送往的老板娘,端茶送水笑容殷勤,一双柔荑却快得让人看不清,她显然不是个寻常女子." },
  [154] = { name="赌徒甲", pai="0", hp=180, maxhp=180, dmg=0, def=0, exp=500, force=0, msg="两眼通红盯着骰盅的赌徒,筹码快输光还不肯走." },
  [155] = { name="赌徒乙", pai="0", hp=190, maxhp=190, dmg=0, def=0, exp=800, force=0, msg="刚赢了钱的赌徒,得意地哼着小曲把玩银锭." },
  [201] = { name="水果", pai="0", hp=50, maxhp=50, dmg=0, def=0, exp=0, force=0, msg="" },
  [202] = { name="小鸡", pai="0", hp=60, maxhp=60, dmg=0, def=0, exp=0, force=0, msg="" },
  [203] = { name="蛇", pai="0", hp=80, maxhp=80, dmg=0, def=0, exp=0, force=0, msg="" },
  [204] = { name="毒蛇", pai="0", hp=400, maxhp=400, dmg=0, def=0, exp=0, force=0, msg="" },
  [205] = { name="管事把头", pai="0", hp=320, maxhp=320, dmg=0, def=0, exp=1100, force=0, msg="密室中管束杂役的管事把头, 颇有些手段, 寻常人不敢靠近." },
  [206] = { name="沈七七", pai="0", hp=560, maxhp=560, dmg=0, def=0, exp=50000, force=10, msg="中日混血的忍者, 七岁起习伊贺忍术, 原为关东军特务, 战后沦为东北土匪." },
  [207] = { name="梅超风", pai="0", hp=460, maxhp=460, dmg=0, def=0, exp=90000, force=15, msg="黑风双煞中的铁尸, 双目已盲却听风辨位, 十指如钩阴狠无比." },
  [208] = { name="卓不凡", pai="0", hp=510, maxhp=510, dmg=0, def=0, exp=130000, force=20, msg="自号剑神的雪山派前辈, 一手剑气纵横曾伤名门高手." },
  [209] = { name="丁春秋", pai="0", hp=3800, maxhp=3800, dmg=0, def=0, exp=5090000, force=179, msg="星宿海的星宿老仙, 一身邪功阴毒无比, 惯以毒粉伤人." },
  [210] = { name="左子穆", pai="0", hp=650, maxhp=650, dmg=0, def=0, exp=520000, force=20, msg="无量剑东宗的掌门, 剑法绵密以柔克刚, 门下弟子众多." },
  [211] = { name="玄难", pai="0", hp=1470, maxhp=1470, dmg=0, def=0, exp=2590000, force=135, msg="少林寺玄字辈的高僧, 达摩院首座, 一身佛门功夫深不可测." },
  [214] = { name="铁匠", pai="0", hp=280, maxhp=280, dmg=0, def=0, exp=1320, force=0, msg="日日在炉火旁挥锤打铁的铁匠, 双臂力大无穷, 寻常人不敢招惹." },
  [215] = { name="红莲守卫", pai="0", hp=350, maxhp=350, dmg=0, def=0, exp=25000, force=0, msg="红莲密室最深处的守卫, 镇守此间多年, 一身功夫不可小觑." },
  [216] = { name="乔峰", pai="0", hp=22800, maxhp=22800, dmg=0, def=0, exp=23000000, force=360, msg="乔峰是丐帮帮主,人称北乔峰.他一套降龙十八掌打得虎虎生风,为人豪气干云,只可惜身世凄苦,终究没能落个好下场." },
  [217] = { name="洪七公", pai="0", hp=9400, maxhp=9400, dmg=0, def=0, exp=9600000, force=226, msg="老叫花一生杀过二百三十一人，个个都是恶徒。" },
  [218] = { name="郭靖", pai="0", hp=19200, maxhp=19200, dmg=0, def=0, exp=19400000, force=324, msg="侠之大者，为国为民。" },
  [219] = { name="虚竹", pai="0", hp=22000, maxhp=22000, dmg=0, def=0, exp=22200000, force=352, msg="虚竹本是少林寺的小沙弥,长得老实本分.可他一破珍珑棋局,白得了逍遥派掌门之位,武功一下子深得连自己都看不懂." },
  [220] = { name="耶律齐", pai="0", hp=1200, maxhp=1200, dmg=0, def=0, exp=1300000, force=100, msg="丐帮弟子，谨守帮规。" },
  [221] = { name="黎生", pai="0", hp=470, maxhp=470, dmg=0, def=0, exp=220000, force=20, msg="洪帮主只传了老汉一招，够用一辈子了。" },
  [222] = { name="史火龙", pai="0", hp=650, maxhp=650, dmg=0, def=0, exp=880000, force=80, msg="老夫练功伤了经脉，久已不问帮中事务。" },
  [223] = { name="段誉", pai="0", hp=21600, maxhp=21600, dmg=0, def=0, exp=21800000, force=348, msg="段誉是大理国的世子,生性文弱,最不爱打打杀杀.可他那一手六脉神剑,加上凌波微步,真打起来江湖上没几个人是他对手." },
  [224] = { name="碧眼狐狸", pai="0", hp=1000, maxhp=1000, dmg=0, def=0, exp=1560000, force=80, msg="花间派的弃徒,李青照的师妹,江湖上有名的大盗,因驻颜有术却又武艺无双而一时名震武林,却在很久之前和独行大侠争斗两败俱伤逃走,独行大侠一直在寻找她." },
  [225] = { name="花十郎", pai="0", hp=1450, maxhp=1450, dmg=0, def=0, exp=2320000, force=125, msg="花十郎是和仲阳的得意弟子,曾经和各大门派高手结下仇怨,不得已和仲阳将其逐出师门随即不知去向." },
  [226] = { name="吕凤先", pai="0", hp=1500, maxhp=1500, dmg=0, def=0, exp=2750000, force=150, msg="兵器谱上排名第九的银戟温侯, 一手银戟使得风流潇洒, 却终究差了几分火候." },
  [227] = { name="赵正义", pai="0", hp=1040, maxhp=1040, dmg=0, def=0, exp=1670000, force=80, msg="少林寺的俗家弟子, 一身外门功夫尚可, 却总爱以正道自居教训旁人." },
  [228] = { name="游龙生", pai="0", hp=1000, maxhp=1000, dmg=0, def=0, exp=1290000, force=80, msg="龙啸云的得意弟子, 江湖上名头不小, 只是实打实的功夫却配不上这份名声." },
  [229] = { name="郭嵩阳", pai="0", hp=1520, maxhp=1520, dmg=0, def=0, exp=3040000, force=160, msg="兵器谱上排名第四的嵩阳铁剑, 为人磊落孤傲, 一柄铁剑走遍天下未曾折腰." },
  [230] = { name="段正淳", pai="0", hp=1700, maxhp=1700, dmg=0, def=0, exp=2020000, force=130, msg="大理国的镇南王, 段誉之父, 一阳指功夫了得却总为情所困." },
  [231] = { name="叶二娘", pai="0", hp=1150, maxhp=1150, dmg=0, def=0, exp=1670000, force=75, msg="四大恶人中的无恶不作, 每日偷抱婴儿把玩, 手段狠辣令人齿冷." },
  [232] = { name="南海鳄神", pai="0", hp=1800, maxhp=1800, dmg=0, def=0, exp=2020000, force=130, msg="四大恶人中的凶神恶煞, 一柄鳄嘴剪凶悍无匹, 偏又痴傻好斗." },
