  [318] = { name="欧阳修", pai="254", hp=2000, maxhp=2000, dmg=0, def=0, exp=10000000, force=1, msg="欧阳修是北宋文坛领袖, 诗文冠绝一时. 他四岁而孤, 家贫无纸, 母亲以荻画地教他写字; 后来主盟文坛, 提携后进无数. 见你远来求学, 便与你讲讲这读书习字的道理." },
  [319] = { name="隐世高人", pai="254", hp=7000, maxhp=7000, dmg=0, def=50, exp=16000000, force=180, msg="一位来历不明的游方客, 据说年轻时曾遍访名师, 基本功夫均已臻化境, 只是深藏不露, 从不轻易与人动手." },
  [320] = { name="宝箱", pai="0", hp=2630, maxhp=2630, dmg=0, def=0, exp=5090000, force=168, msg="一只落满灰尘的乌木宝箱, 上面嵌着黄铜锁扣, 不知是哪一代闯关者留下的." },
  [321] = { name="桃根仙", pai="0", hp=1000, maxhp=1000, dmg=0, def=0, exp=1380000, force=70, msg="桃谷六仙之一，相貌奇丑，说话颠三倒四，六兄弟心意相通，联手难缠。" },
  [322] = { name="桃干仙", pai="0", hp=1000, maxhp=1000, dmg=0, def=0, exp=1380000, force=70, msg="桃谷六仙之一，圆头圆脑，爱与人抬杠，一张嘴从不饶人。" },
  [323] = { name="桃枝仙", pai="0", hp=1000, maxhp=1000, dmg=0, def=0, exp=1380000, force=70, msg="桃谷六仙之一，瘦骨嶙峋，说话前言不搭后语，身法却奇快。" },
  [324] = { name="桃叶仙", pai="0", hp=1000, maxhp=1000, dmg=0, def=0, exp=1380000, force=70, msg="桃谷六仙之一，矮胖身材，最爱插科打诨，出手却毫不含糊。" },
  [325] = { name="桃花仙", pai="0", hp=1030, maxhp=1030, dmg=0, def=0, exp=1410000, force=72, msg="桃谷六仙之一，尖嘴猴腮，笑起来皱成一团，武功却极怪异。" },
  [326] = { name="桃实仙", pai="0", hp=1030, maxhp=1030, dmg=0, def=0, exp=1410000, force=72, msg="桃谷六仙之一，膀大腰圆，说话瓮声瓮气，六兄弟中气力最足。" },
  [327] = { name="侯通海", pai="0", hp=1030, maxhp=1030, dmg=0, def=0, exp=1530000, force=72, msg="人称三头蛟，完颜洪烈帐下武人，使一柄三股叉，行事鲁莽凶横。" },
  [328] = { name="沙通天", pai="0", hp=1030, maxhp=1030, dmg=0, def=0, exp=1530000, force=72, msg="鬼门龙王，黄河边一霸，水中陆上功夫俱佳，依附完颜洪烈为虎作伥。" },
  [329] = { name="彭连虎", pai="0", hp=1060, maxhp=1060, dmg=0, def=0, exp=1570000, force=75, msg="千手人屠，黑道巨擘，身手狠辣刁钻，专一杀人越货。" },
  [330] = { name="梁子翁", pai="0", hp=1060, maxhp=1060, dmg=0, def=0, exp=1570000, force=75, msg="参仙老怪，长白山采药炼药成名，使一条软鞭，阴险多诈。" },
  [331] = { name="灵智上人", pai="0", hp=1060, maxhp=1060, dmg=0, def=0, exp=1570000, force=75, msg="西藏密宗高手，修习大手印，掌力沉雄，为完颜洪烈座上客。" },
  [332] = { name="木高峰", pai="0", hp=1060, maxhp=1060, dmg=0, def=0, exp=1570000, force=75, msg="人称塞北明驼，身背驼峰，掌力阴毒，江湖中令人闻之色变。" },
  [333] = { name="田归农", pai="0", hp=1090, maxhp=1090, dmg=0, def=0, exp=1570000, force=76, msg="天龙门掌门，剑法精严，城府极深，为夺宝不择手段。" },
  [334] = { name="柯镇恶", pai="0", hp=1090, maxhp=1090, dmg=0, def=0, exp=1630000, force=76, msg="江南七怪之首，双目失明却听风辨位，铁杖纵横，侠义刚直。" },
  [335] = { name="朱聪", pai="0", hp=1090, maxhp=1090, dmg=0, def=0, exp=1630000, force=76, msg="江南七怪之一，号妙手书生，手执铁扇，妙手空空，足智多谋。" },
  [336] = { name="韩宝驹", pai="0", hp=1090, maxhp=1090, dmg=0, def=0, exp=1630000, force=76, msg="江南七怪之一，号马王神，善相马驭马，使一条软鞭。" },
  [337] = { name="南希仁", pai="0", hp=1120, maxhp=1120, dmg=0, def=0, exp=1650000, force=78, msg="江南七怪之一，沉默寡言，一身横练功夫，扁担使得出神入化。" },
  [338] = { name="张阿生", pai="0", hp=1120, maxhp=1120, dmg=0, def=0, exp=1650000, force=78, msg="江南七怪之一，屠户出身，身大力沉，一柄屠刀使得虎虎生风。" },
  [339] = { name="全金发", pai="0", hp=1120, maxhp=1120, dmg=0, def=0, exp=1650000, force=78, msg="江南七怪之一，市井商贩打扮，以刀为兵，精于算计。" },
  [340] = { name="韩小莹", pai="0", hp=1120, maxhp=1120, dmg=0, def=0, exp=1650000, force=78, msg="江南七怪之一，号越女剑，七怪中年纪最幼，剑法轻灵迅捷。" },
  [341] = { name="鲁有脚", pai="0", hp=1150, maxhp=1150, dmg=0, def=0, exp=1680000, force=80, msg="丐帮四大长老之一，为人忠厚，一根竹棒使的打狗棒法颇有火候。" },
  [342] = { name="简长老", pai="0", hp=1150, maxhp=1150, dmg=0, def=0, exp=1680000, force=80, msg="丐帮四大长老之一，资历最深，打狗棒法醇厚老辣。" },
  [343] = { name="彭长老", pai="0", hp=1150, maxhp=1150, dmg=0, def=0, exp=1680000, force=80, msg="丐帮四大长老之一，心思深沉，棒法绵密。" },
  [344] = { name="梁长老", pai="0", hp=1150, maxhp=1150, dmg=0, def=0, exp=1680000, force=80, msg="丐帮四大长老之一，性情暴烈，一根棒使得又快又狠。" },
  [345] = { name="吴长老", pai="0", hp=1180, maxhp=1180, dmg=0, def=0, exp=1700000, force=82, msg="丐帮长老，行事稳重，打狗棒法沉稳老练。" },
  [346] = { name="史仲猛", pai="0", hp=1180, maxhp=1180, dmg=0, def=0, exp=1720000, force=82, msg="万兽山庄史家兄弟之一，拳法如猛虎扑食，刚猛无俦。" },
  [347] = { name="史季强", pai="0", hp=1180, maxhp=1180, dmg=0, def=0, exp=1720000, force=82, msg="万兽山庄史家兄弟之一，鹰爪功凌厉，专袭敌人关节要害。" },
  [348] = { name="史叔刚", pai="0", hp=1180, maxhp=1180, dmg=0, def=0, exp=1720000, force=82, msg="万兽山庄史家兄弟之一，拳路灵巧如猿，招招点到即止。" },
  [349] = { name="田伯光", pai="0", hp=1220, maxhp=1220, dmg=0, def=0, exp=1830000, force=85, msg="人称万里独行，轻功绝顶，一柄快刀使得迅雷不及掩耳。" },
  [350] = { name="不戒和尚", pai="0", hp=1220, maxhp=1220, dmg=0, def=0, exp=1830000, force=85, msg="身形魁梧的野和尚，一身蛮力惊人，内功却极为深厚。" },
  [351] = { name="余沧海", pai="0", hp=1220, maxhp=1220, dmg=0, def=0, exp=1830000, force=85, msg="青城派掌门，剑法狠辣，为夺辟邪剑谱不择手段。" },
  [352] = { name="任盈盈", pai="0", hp=1260, maxhp=1260, dmg=0, def=0, exp=1850000, force=88, msg="日月神教圣姑，容貌绝丽，通晓音律，手下皆服其能。" },
  [353] = { name="曲洋", pai="0", hp=1260, maxhp=1260, dmg=0, def=0, exp=1850000, force=88, msg="日月神教长老，擅琴，与刘正风以音律相交，为知己生死不悔。" },
  [354] = { name="刘正风", pai="0", hp=1260, maxhp=1260, dmg=0, def=0, exp=1850000, force=88, msg="衡山派高手，剑法儒雅，欲金盆洗手脱离江湖，终为所累。" },
  [355] = { name="何太冲", pai="0", hp=1200, maxhp=1200, dmg=0, def=0, exp=1710000, force=90, msg="昆仑派掌门，铁琴先生，剑法精妙却性情凉薄，惯以名门自居。" },
  [356] = { name="莫大先生", pai="0", hp=1200, maxhp=1200, dmg=0, def=0, exp=1710000, force=90, msg="衡山派掌门，人称潇湘夜雨，一柄长剑藏在胡琴之中，出手迅捷如电。" },
  [357] = { name="定闲", pai="0", hp=1200, maxhp=1200, dmg=0, def=0, exp=1710000, force=90, msg="恒山派掌门，性情慈悲而刚正，剑法绵密，为五岳剑派中难得的中立长者。" },
  [358] = { name="宋青书", pai="0", hp=1250, maxhp=1250, dmg=0, def=0, exp=1720000, force=95, msg="武当派第三代弟子中的翘楚，眉目俊朗却心术不正，为情所困终堕歧途。" },
  [359] = { name="木桑道人", pai="0", hp=1250, maxhp=1250, dmg=0, def=0, exp=1720000, force=95, msg="铁剑门前辈高人，棋艺武功俱臻化境，生性诙谐，游戏人间。" },
  [360] = { name="龙啸云", pai="0", hp=1250, maxhp=1250, dmg=0, def=0, exp=1800000, force=95, msg="威震河朔的豪杰，重义气却心机深沉，一柄剑下不知多少恩怨。" },
  [361] = { name="荆无命", pai="0", hp=1250, maxhp=1250, dmg=0, def=0, exp=1800000, force=95, msg="右手剑快如闪电的冷面剑客，沉默寡言，剑出必见血。" },
  [362] = { name="胡不归", pai="0", hp=1300, maxhp=1300, dmg=0, def=0, exp=1810000, force=100, msg="江湖上身份不明的怪客，行踪飘忽，一柄长剑来去无踪。" },
  [363] = { name="姬冰雁", pai="0", hp=1300, maxhp=1300, dmg=0, def=0, exp=1830000, force=100, msg="富甲一方的巨贾，也是轻功绝顶的剑客，为人精明而不失侠义。" },
  [364] = { name="胡铁花", pai="0", hp=1300, maxhp=1300, dmg=0, def=0, exp=1830000, force=100, msg="楚留香挚友，嗜酒如命的豪爽大汉，铁掌开碑，最重朋友义气。" },
  [365] = { name="中原一点红", pai="0", hp=1300, maxhp=1300, dmg=0, def=0, exp=1830000, force=100, msg="神秘杀手，剑尖沾血只留一点红，出手无情却对楚留香另眼相看。" },
  [366] = { name="无花", pai="0", hp=1350, maxhp=1350, dmg=0, def=0, exp=1970000, force=105, msg="少林寺出身的绝代高僧，琴棋书画样样精通，温文尔雅之下另有隐情。" },
  [367] = { name="原随云", pai="0", hp=1350, maxhp=1350, dmg=0, def=0, exp=1970000, force=105, msg="无争山庄少庄主，双目失明却听觉通神，潇洒从容，深不可测。" },
  [368] = { name="薛衣人", pai="0", hp=1350, maxhp=1350, dmg=0, def=0, exp=1970000, force=105, msg="人称血衣人的剑道宗师，剑法凌厉刚猛，天下难逢敌手。" },
  [369] = { name="花满楼", pai="0", hp=1350, maxhp=1350, dmg=0, def=0, exp=1970000, force=105, msg="江南花家七公子，双目失明而心境澄明，温润如玉，一阳指精妙绝伦。" },
  [370] = { name="司空摘星", pai="0", hp=1400, maxhp=1400, dmg=0, def=0, exp=2040000, force=110, msg="江湖第一神偷，轻功天下无双，手爪如钩，来去无影。" },
  [371] = { name="老实和尚", pai="0", hp=1400, maxhp=1400, dmg=0, def=0, exp=2040000, force=110, msg="少林寺的怪和尚，口称老实实则机变百出，拳力沉雄。" },
  [372] = { name="宫九", pai="0", hp=1400, maxhp=1400, dmg=0, def=0, exp=2040000, force=110, msg="神秘帮派的少主，剑法诡异狠辣，行事乖张，令人捉摸不透。" },
  [373] = { name="小鱼儿", pai="0", hp=1400, maxhp=1400, dmg=0, def=0, exp=2040000, force=110, msg="恶人谷中长大的机灵小子，聪明绝顶，拳脚刁钻，专会戏弄强敌。" },
  [374] = { name="花无缺", pai="0", hp=1450, maxhp=1450, dmg=0, def=0, exp=2160000, force=115, msg="移花宫少主，风采绝世，武功卓绝，一阳指与移花接玉名动天下。" },
  [375] = { name="黑蜘蛛", pai="0", hp=1450, maxhp=1450, dmg=0, def=0, exp=2160000, force=115, msg="来去如风的独行客，身法诡异，爪法凌厉，专与负心人作对。" },
  [376] = { name="轩辕三光", pai="0", hp=1450, maxhp=1450, dmg=0, def=0, exp=2160000, force=115, msg="嗜赌如命的江湖奇人，赌钱赌命赌武功，一柄快刀从不服输。" },
  [377] = { name="萧十一郎", pai="0", hp=1500, maxhp=1500, dmg=0, def=0, exp=2190000, force=120, msg="独来独往的盗马贼，一柄割鹿刀横行天下，性情孤傲而心地仁厚。" },
  [378] = { name="连城璧", pai="0", hp=1500, maxhp=1500, dmg=0, def=0, exp=2190000, force=120, msg="无垢山庄少庄主，风采翩翩的剑术名家，娶得美人却心怀城府。" },
  [379] = { name="逍遥侯", pai="0", hp=1500, maxhp=1500, dmg=0, def=0, exp=2190000, force=120, msg="神秘莫测的侯爷，武功诡异通玄，暗中操控江湖无数阴谋。" },
  [380] = { name="风四娘", pai="0", hp=1500, maxhp=1500, dmg=0, def=0, exp=2190000, force=120, msg="风一样的女子，泼辣豪爽又风情万种，轻功暗器俱佳。" },
  [381] = { name="孟星魂", pai="0", hp=1550, maxhp=1550, dmg=0, def=0, exp=2320000, force=125, msg="快活林的第一杀手，剑快心冷，却在血腥中渴望着真情。" },
  [382] = { name="律香川", pai="0", hp=1550, maxhp=1550, dmg=0, def=0, exp=2320000, force=125, msg="老伯的义子，心思缜密，剑法沉稳，为达目的隐忍深沉。" },
  [383] = { name="高老大", pai="0", hp=1550, maxhp=1550, dmg=0, def=0, exp=2320000, force=125, msg="快活林的主人，美艳而心狠的女中枭雄，爪法诡谲，掌控无数杀手。" },
  [384] = { name="白自在", pai="0", hp=1600, maxhp=1600, dmg=0, def=0, exp=2430000, force=130, msg="雪山派掌门，自大成狂，号威德先生，内功深厚剑法凌厉。" },
  [385] = { name="谢烟客", pai="0", hp=1600, maxhp=1600, dmg=0, def=0, exp=2430000, force=130, msg="摩天崖上神龙见首不见尾的怪人，七伤拳刚猛无俦，行事亦正亦邪。" },
  [386] = { name="贝海石", pai="0", hp=1600, maxhp=1600, dmg=0, def=0, exp=2430000, force=130, msg="长乐帮实际掌权者，医术通神，心机深沉，一身武功深藏不露。" },
  [387] = { name="阿凡提", pai="0", hp=1600, maxhp=1600, dmg=0, def=0, exp=2430000, force=130, msg="骑着小毛驴的西域名士，机智幽默爱管不平事，一把鹰爪手出神入化。" },
  [388] = { name="空闻", pai="0", hp=1650, maxhp=1650, dmg=0, def=0, exp=2500000, force=135, msg="少林寺方丈，神僧空见的师兄，德高望重，一身佛门神功已臻化境。" },
  [389] = { name="空智", pai="0", hp=1650, maxhp=1650, dmg=0, def=0, exp=2500000, force=135, msg="少林寺达摩院首座，通晓七十二绝技十一门，拳法刚猛深沉。" },
  [390] = { name="文泰来", pai="0", hp=1650, maxhp=1650, dmg=0, def=0, exp=2590000, force=140, msg="红花会四当家，号奔雷手，豪气干云，斗转星移变化无穷。" },
  [391] = { name="赵半山", pai="0", hp=1650, maxhp=1650, dmg=0, def=0, exp=2590000, force=140, msg="红花会三当家，人称千臂如来，暗器与拳掌俱臻绝顶，仁厚长者。" },
  [392] = { name="花铁干", pai="0", hp=1700, maxhp=1700, dmg=0, def=0, exp=2590000, force=140, msg="南四奇之一，鹰爪铁枪门门主，武功高强，临危却暴露卑劣本性。" },
  [393] = { name="陆菲青", pai="0", hp=1700, maxhp=1700, dmg=0, def=0, exp=2590000, force=140, msg="武当派隐世名宿，绵里藏针陆菲青，剑法精纯，为师门清理门户。" },
  [394] = { name="张召重", pai="0", hp=1700, maxhp=1700, dmg=0, def=0, exp=2590000, force=140, msg="武当派叛逆，人称火手判官，剑法狠辣，贪图富贵残害同门。" },
  [395] = { name="九难", pai="0", hp=1750, maxhp=1750, dmg=0, def=0, exp=2670000, force=145, msg="前明长平公主，独臂神尼，铁剑门传人，剑法玄妙，心怀复国大志。" },
  [396] = { name="陈近南", pai="0", hp=1750, maxhp=1750, dmg=0, def=0, exp=2670000, force=145, msg="天地会总舵主，平生不识陈近南便称英雄也枉然，剑法儒雅内力深厚。" },
  [397] = { name="冯锡范", pai="0", hp=1750, maxhp=1750, dmg=0, def=0, exp=2670000, force=145, msg="郑家一等侍卫，一剑无血冯锡范，剑法阴狠毒辣，专擅权术。" },
  [398] = { name="洪安通", pai="0", hp=1750, maxhp=1750, dmg=0, def=0, exp=2670000, force=145, msg="神龙教教主，武功登峰造极，练就一身邪功，喜怒无常阴狠残酷。" },
  [399] = { name="沈浪", pai="0", hp=1850, maxhp=1850, dmg=0, def=0, exp=2780000, force=150, msg="九州王沈天君的独子，风流潇洒智计无双，剑法已达化境。" },
  [400] = { name="王怜花", pai="0", hp=1850, maxhp=1850, dmg=0, def=0, exp=2780000, force=150, msg="千面公子王怜花，精通易容医毒，剑法诡异，亦正亦邪。" },
  [401] = { name="熊猫儿", pai="0", hp=1850, maxhp=1850, dmg=0, def=0, exp=2780000, force=150, msg="豪爽率直的少年侠士，酒量惊人，猛虎拳刚猛，与沈浪生死相交。" },
  [402] = { name="快活王", pai="0", hp=1850, maxhp=1850, dmg=0, def=0, exp=2780000, force=150, msg="快活王柴玉关，野心滔天的枭雄，武功盖世，为夺秘笈不择手段。" },
  [403] = { name="白飞飞", pai="0", hp=1850, maxhp=1850, dmg=0, def=0, exp=2780000, force=150, msg="幽灵宫主，身世凄苦容貌绝世，武功诡异莫测，心思缜密。" },
  [404] = { name="方宝玉", pai="0", hp=1900, maxhp=1900, dmg=0, def=0, exp=2890000, force=155, msg="名门之后，聪明绝顶，历经磨难终成剑道大家，一身正气。" },
  [405] = { name="紫衣侯", pai="0", hp=1900, maxhp=1900, dmg=0, def=0, exp=2890000, force=155, msg="武林中的神秘侯爷，紫衣飘飘剑法通神，暗中守护中原武学。" },
  [406] = { name="白衣人", pai="0", hp=1900, maxhp=1900, dmg=0, def=0, exp=2890000, force=155, msg="来自东瀛的绝顶剑客，一袭白衣，剑法凌厉，只为挑战中原高手。" },
  [407] = { name="木道人", pai="0", hp=7000, maxhp=7000, dmg=0, def=0, exp=7200000, force=202, msg="武当派前辈, 剑法通神, 却因参悟天道而堕入魔道, 行事高深莫测。" },
  [408] = { name="陆小凤", pai="0", hp=7200, maxhp=7200, dmg=0, def=0, exp=7400000, force=204, msg="四条眉毛的传奇人物, 灵犀一指妙绝天下, 机智风趣, 最爱管闲事。" },
  [409] = { name="楚留香", pai="0", hp=7200, maxhp=7200, dmg=0, def=0, exp=7400000, force=204, msg="盗帅夜留香, 轻功绝世, 从不杀人, 风流倜傥智计无双。" },
  [410] = { name="石观音", pai="0", hp=7400, maxhp=7400, dmg=0, def=0, exp=7600000, force=206, msg="容貌绝世的女魔头, 精擅摄魂之术与毒功, 野心极大心狠手辣。" },
  [411] = { name="阿飞", pai="0", hp=7600, maxhp=7600, dmg=0, def=0, exp=7800000, force=208, msg="快剑如风的少年剑客, 剑比闪电还快, 沉默孤傲重情重义。" },
  [412] = { name="傅红雪", pai="0", hp=7600, maxhp=7600, dmg=0, def=0, exp=7800000, force=208, msg="苍白的手漆黑的刀, 刀一出鞘必见血, 一生为仇恨所困。" },
  [413] = { name="叶开", pai="0", hp=7800, maxhp=7800, dmg=0, def=0, exp=8000000, force=210, msg="小李飞刀的传人, 飞刀一出例不虚发, 天性开朗心怀慈悲。" },
  [414] = { name="铁中棠", pai="0", hp=7800, maxhp=7800, dmg=0, def=0, exp=8000000, force=210, msg="大旗门的少主, 智勇双全, 忍辱负重终成大器。" },
  [415] = { name="夜帝", pai="0", hp=8000, maxhp=8000, dmg=0, def=0, exp=8200000, force=212, msg="神秘莫测的绝顶高手, 自号夜帝, 一身武功深不可测。" },
  [416] = { name="鹿杖客", pai="0", hp=8200, maxhp=8200, dmg=0, def=0, exp=8400000, force=214, msg="玄冥二老之一, 好色贪财, 玄冥神掌阴寒彻骨。" },
  [417] = { name="鹤笔翁", pai="0", hp=8200, maxhp=8200, dmg=0, def=0, exp=8400000, force=214, msg="玄冥二老之一, 喜杯中之物, 与鹿杖客搭档横行江湖。" },
  [418] = { name="渡难", pai="0", hp=8400, maxhp=8400, dmg=0, def=0, exp=8600000, force=216, msg="少林三渡之一, 坐禅数十年, 武功已臻化境。" },
  [419] = { name="渡劫", pai="0", hp=8400, maxhp=8400, dmg=0, def=0, exp=8600000, force=216, msg="少林三渡之一, 面壁参禅, 一身佛门神功登峰造极。" },
  [420] = { name="渡厄", pai="0", hp=8400, maxhp=8400, dmg=0, def=0, exp=8600000, force=216, msg="少林三渡之首, 辈分最高, 武功最为精深。" },
  [421] = { name="成昆", pai="0", hp=8600, maxhp=8600, dmg=0, def=0, exp=8800000, force=218, msg="混元霹雳手, 阴险歹毒, 一手幻阴指暗算无数英雄。" },
  [422] = { name="空见神僧", pai="0", hp=8600, maxhp=8600, dmg=0, def=0, exp=8800000, force=218, msg="少林四大神僧之首, 金刚不坏体神功天下无敌, 慈悲为怀。" },
  [423] = { name="任我行", pai="0", hp=8800, maxhp=8800, dmg=0, def=0, exp=9000000, force=220, msg="日月神教前教主, 吸星大法吸人内力, 霸气张狂。" },
  [424] = { name="阳顶天", pai="0", hp=8800, maxhp=8800, dmg=0, def=0, exp=9000000, force=220, msg="明教第三十三代教主, 乾坤大挪移出神入化, 威震天下。" },
  [425] = { name="令狐冲", pai="0", hp=9200, maxhp=9200, dmg=0, def=0, exp=9400000, force=224, msg="华山派大弟子, 习得独孤九剑, 任侠仗义笑傲江湖。" },
  [426] = { name="方证大师", pai="0", hp=9200, maxhp=9200, dmg=0, def=0, exp=9400000, force=224, msg="少林方丈, 易筋经已至化境, 为武林中流砥柱。" },
  [427] = { name="欧阳锋", pai="0", hp=9400, maxhp=9400, dmg=0, def=0, exp=9600000, force=226, msg="西毒欧阳锋, 蛤蟆功天下无双, 逆练九阴真经终成疯子。" },
  [428] = { name="黄药师", pai="0", hp=9800, maxhp=9800, dmg=0, def=0, exp=10000000, force=230, msg="东邪黄药师, 博通奇门五行, 弹指神通与玉箫剑法冠绝当世。" },
  [429] = { name="一灯大师", pai="0", hp=9800, maxhp=9800, dmg=0, def=0, exp=10000000, force=230, msg="南帝一灯大师, 一阳指功力深厚, 出家为僧普度众生。" },
  [430] = { name="鸠摩智", pai="0", hp=10200, maxhp=10200, dmg=0, def=0, exp=10400000, force=234, msg="吐蕃国师, 火焰刀与小无相功名震西域, 武学奇才。" },
  [431] = { name="萧远山", pai="0", hp=10600, maxhp=10600, dmg=0, def=0, exp=10800000, force=238, msg="契丹高手, 萧峰之父, 一身武功深不可测, 隐忍数十年。" },
  [432] = { name="慕容博", pai="0", hp=10600, maxhp=10600, dmg=0, def=0, exp=10800000, force=238, msg="姑苏慕容家主, 斗转星移以彼之道还施彼身, 心机深沉。" },
  [433] = { name="厉胜男", pai="0", hp=10800, maxhp=10800, dmg=0, def=0, exp=11000000, force=240, msg="天山派奇女子, 剑法凌厉, 性情刚烈, 敢爱敢恨。" },
  [434] = { name="孟神通", pai="0", hp=10800, maxhp=10800, dmg=0, def=0, exp=11000000, force=240, msg="邪派宗师, 武功诡异狠毒, 为练神功不择手段。" },
  [435] = { name="白发魔女", pai="0", hp=11200, maxhp=11200, dmg=0, def=0, exp=11400000, force=244, msg="练霓裳, 一夜白头, 剑法凌厉如霜, 爱恨分明。" },
  [436] = { name="晦明禅师", pai="0", hp=11200, maxhp=11200, dmg=0, def=0, exp=11400000, force=244, msg="天山派开山祖师, 剑法通神, 德高望重。" },
  [437] = { name="乔北溟", pai="0", hp=11800, maxhp=11800, dmg=0, def=0, exp=12000000, force=250, msg="武林第一魔头, 武功盖世, 毕生欲称霸江湖。" },
  [438] = { name="李秋水", pai="0", hp=12000, maxhp=12000, dmg=0, def=0, exp=12200000, force=252, msg="逍遥派传人, 白虹掌力出神入化, 容貌美艳心狠手辣。" },
  [439] = { name="天山童姥", pai="0", hp=12000, maxhp=12000, dmg=0, def=0, exp=12200000, force=252, msg="逍遥派大师姐, 天山六阳掌与生死符令人闻风丧胆。" },
  [440] = { name="无崖子", pai="0", hp=12200, maxhp=12200, dmg=0, def=0, exp=12400000, force=254, msg="逍遥派掌门, 北冥神功与凌波微步冠绝天下, 一代宗师。" },
  [441] = { name="积分使者", pai="256", hp=500, maxhp=500, dmg=0, def=0, exp=0, force=0, msg="积分使者掌管着积分宝库, 只要你有足够的积分, 便可换得稀世奇珍。" },
  [442] = { name="死死若丸", pai="0", hp=12600, maxhp=12600, dmg=0, def=0, exp=12800000, force=258, msg="区区人类,也配挡在本大爷的妖刀面前?哼——我这柄魔哭鸣斩刃,正想尝尝鲜血的滋味。" },
  [443] = { name="张无忌", pai="0", hp=20200, maxhp=20200, dmg=0, def=0, exp=20400000, force=334, msg="张无忌是武当张真人的师侄,又是明教教主.武功之高已是天下第一等,可惜总是个心软的性子." },
  [444] = { name="杨过", pai="0", hp=19600, maxhp=19600, dmg=0, def=0, exp=19800000, force=328, msg="杨过是神雕大侠,断了一臂却自成一家.他自创黯然销魂掌,武功之高当世少有敌手,与小龙女携手归隐终南,江湖只留下传说." },
  [445] = { name="周伯通", pai="0", hp=18600, maxhp=18600, dmg=0, def=0, exp=18800000, force=318, msg="周伯通人称老顽童,整天嘻嘻哈哈没个正经.他自创双手互搏之术,又把九阴真经练了个透,武功高得连东邪西毒都佩服." },
  [446] = { name="东方不败", pai="0", hp=21200, maxhp=21200, dmg=0, def=0, exp=21400000, force=344, msg="东方不败是日月神教教主,自从练了葵花宝典便不男不女,武功却高得吓人.他一根绣花针使得出神入化,任你天王老子也近不了身." },
  [447] = { name="王重阳", pai="0", hp=17400, maxhp=17400, dmg=0, def=0, exp=17600000, force=306, msg="王重阳是全真教创派祖师,华山论剑技压群雄,夺得天下第一.他一生立志抗金,却又淡泊名利,把一身武功传给了全真七子." },
  [448] = { name="林朝英", pai="0", hp=17800, maxhp=17800, dmg=0, def=0, exp=18000000, force=310, msg="林朝英是古墓派创派祖师,武功直追王重阳.她与王重阳一生相恋相敬,却终究未能结为连理,只留下玉女心经与一世痴情." },
  [449] = { name="风清扬", pai="0", hp=20600, maxhp=20600, dmg=0, def=0, exp=20800000, force=338, msg="风清扬是华山派剑宗前辈,人称剑圣.他一生痴于剑道,自创独孤九剑,晚年归隐思过崖,江湖上再没人见过他出手." },
  [450] = { name="邀月宫主", pai="0", hp=13000, maxhp=13000, dmg=0, def=0, exp=13200000, force=262, msg="邀月宫主是移花宫的大宫主,容貌绝艳却冷若冰霜.她与妹妹怜星并称移花双绝,一手移花接玉,江湖上无人能接得下." },
  [451] = { name="燕南天", pai="0", hp=13600, maxhp=13600, dmg=0, def=0, exp=13800000, force=268, msg="燕南天是天下第一神剑,为人豪气干云.他那一柄神剑使得神鬼皆惊,只可惜为了个不成器的兄弟,落得一身是伤." },
  [452] = { name="小老头", pai="0", hp=15000, maxhp=15000, dmg=0, def=0, exp=15200000, force=282, msg="吴明人称小老头,看着干瘪瘦小,实则一身武功是当世一绝.他隐居世外,谁知他深浅的,整个江湖也找不出几个." },
  [453] = { name="水母阴姬", pai="0", hp=13600, maxhp=13600, dmg=0, def=0, exp=13800000, force=268, msg="水母阴姬是神水宫宫主,武功阴柔诡异,江湖上敢惹她的没有几个.她为人骄傲自负,偏偏又最恨男人,行事全凭一时喜怒." },
  [454] = { name="李寻欢", pai="0", hp=14400, maxhp=14400, dmg=0, def=0, exp=14600000, force=276, msg="李寻欢人称小李探花,一把飞刀例不虚发.他文采风流,可惜一生为情所困,手上那把小刀却从来不曾失手." },
  [455] = { name="上官金虹", pai="0", hp=14800, maxhp=14800, dmg=0, def=0, exp=15000000, force=280, msg="上官金虹是金钱帮帮主,心狠手辣,武功之高不在小李飞刀之下.他一心只想与李寻欢一决高下,称霸天下武林." },
  [456] = { name="西门吹雪", pai="0", hp=15400, maxhp=15400, dmg=0, def=0, exp=15600000, force=286, msg="西门吹雪是万梅山庄庄主,剑法冷冽如雪.他一生只求完剑,出剑必见血,江湖上凡想跟他比剑的人,没有几个能活着离开." },
  [457] = { name="叶孤城", pai="0", hp=15800, maxhp=15800, dmg=0, def=0, exp=16000000, force=290, msg="叶孤城是白云城城主,一手天外飞仙剑法孤高绝世.他一生只求与西门吹雪一战,为这一战即便身死也无憾." },
  [458] = { name="谢晓峰", pai="0", hp=16400, maxhp=16400, dmg=0, def=0, exp=16600000, force=296, msg="谢晓峰是神剑山庄的少庄主,人称剑神.他剑法通神,本已天下无敌,却偏偏厌倦了江湖纷争,一心只想过清静日子." },
  [459] = { name="燕十三", pai="0", hp=16800, maxhp=16800, dmg=0, def=0, exp=17000000, force=300, msg="燕十三是剑客,自创夺命十三剑.他一生只求与谢晓峰一战,剑法狠绝,连神剑山庄都忌他三分." },
  [460] = { name="元十三限", pai="0", hp=23000, maxhp=23000, dmg=0, def=0, exp=23200000, force=362, msg="元十三限是天下第一剑,一生只为剑道而生.他武功高得连四大名捕联手都讨不了好." },
  [461] = { name="关七", pai="0", hp=23800, maxhp=23800, dmg=0, def=0, exp=24000000, force=370, msg="关七本名关木旦, 是迷天盟七圣主, 人称战神、天敌. 他不用刀不用剑, 独门绝学「先天破体无形剑气」号称剑气极致——剑气可自体内体外任意部位发出, 随手挥洒无意运聚便能伤人. 当年他带着镣铐独战群雄, 依然游刃有余, 江湖上提起七爷无人不惧." },
  [462] = { name="萧秋水", pai="0", hp=24200, maxhp=24200, dmg=0, def=0, exp=24400000, force=374, msg="萧秋水是神州奇侠,胸怀天下,武功自成一派.他创出忘情天书,虽自谦说不过是一家之言,可江湖上能接他一剑的人却没有几个." },
  [463] = { name="扫地僧", pai="0", hp=24800, maxhp=24800, dmg=0, def=0, exp=25000000, force=380, msg="扫地僧是藏经阁的扫地老僧,白日扫经,夜里诵佛,谁见他都只当是个寻常老人.可萧远山慕容博两大高手在他面前一招都讨不了好,武功之高当世无人能及." },
  [464] = { name="步惊云", pai="0", hp=17200, maxhp=17200, dmg=0, def=0, exp=17400000, force=304, msg="步惊云是雄霸的二弟子, 人称不哭死神. 他性情孤冷, 不苟言笑, 一手排云掌使得是雄浑无匹; 后得麒麟臂, 武功更是精进如飞." },
  [465] = { name="聂风", pai="0", hp=18200, maxhp=18200, dmg=0, def=0, exp=18400000, force=314, msg="聂风是雄霸的三弟子, 生性洒脱仁厚, 风神腿轻捷如风. 他修行聂家冰心诀, 虽体质有异, 却也因此练成了一身惊世骇俗的轻功." },
  [466] = { name="雄霸", pai="0", hp=20000, maxhp=20000, dmg=0, def=0, exp=20200000, force=332, msg="雄霸是天下会帮主, 一方枭雄. 他融天霜拳、排云掌、风神腿三家之长, 创出三分归元气, 曾以批命箴言搅动整个武林风云." },
  [467] = { name="云游散人", pai="254", hp=10000, maxhp=10000, dmg=0, def=50, exp=20000000, force=200, msg="一位行踪无定的云游散人, 据说与隐世高人同出一门. 他毕生精研天下各派的基本功夫, 拳脚兵刃轻功内功无一不精, 皆已臻化境, 却从不以武功自矜, 亦不轻易与人动手." },
  [468] = { name="天机老人", pai="254", hp=14000, maxhp=14000, dmg=0, def=50, exp=30000000, force=240, msg="一位白发苍苍的老者, 自称天机老人, 在密室深处静坐多年. 他博通天下各门各派的基本功夫, 拳脚兵刃轻功内功无一不精, 皆已臻至四百年功力, 却只肯点拨有缘之人." },
  [469] = { name="太虚真人", pai="254", hp=18000, maxhp=18000, dmg=0, def=50, exp=40000000, force=280, msg="密室最深处的石台上, 端坐着一位须发皆白的老道, 自称太虚真人. 相传他百年前便已通晓天下武学, 十项基本功夫俱臻四百五十年功力, 早已不滞于物; 只是他惯于静观, 唯有点化有缘之人才肯开口." },
  [470] = { name="户愚吕兄", pai="0", hp=21000, maxhp=21000, dmg=0, def=0, exp=21200000, force=342, msg="户愚吕兄是户愚吕兄弟中的兄长, 一身妖力尽在\"变\"字: 可随意改变形体, 更能化作兵刃供弟弟执用. 他心思阴狠, 惯于躲在暗处算计, 单打独斗虽不及弟弟, 却也绝不是易与之辈." },
  [471] = { name="藏马", pai="0", hp=22400, maxhp=22400, dmg=0, def=0, exp=22600000, force=356, msg="藏马本是魔界极恶盗贼妖狐, 因重伤附身于人类胎儿而降生人间. 他生性沉静多谋, 惯以智计取胜; 一手蔷薇棘鞭与植物操使, 出手优雅而杀机四伏." },
  [472] = { name="飞影", pai="0", hp=23400, maxhp=23400, dmg=0, def=0, exp=23600000, force=366, msg="飞影生而为忌子, 自幼被弃, 靠一身妖气与邪眼在魔界杀出一条生路. 他沉默寡言、出手狠辣, 邪王炎杀拳与黑龙波一出, 连魔界强者也要退避三舍." },
  [473] = { name="户愚吕弟", pai="0", hp=24400, maxhp=24400, dmg=0, def=0, exp=24600000, force=376, msg="户愚吕弟曾是追随幻海的人类武者, 因恐惧衰老而堕入魔道, 成为暗黑武术会最强的人形妖怪. 他将一身筋肉练至极致, 更可化为百分之百的妖怪形态, 超A级的妖力压得所有对手喘不过气." },
  [474] = { name="苏轼", pai="254", hp=8000, maxhp=8000, dmg=0, def=0, exp=14000000, force=1, msg="苏轼字子瞻, 号东坡居士, 眉州眉山人. 他诗词文书画无一不精, 位列唐宋八大家; 一生三起三落, 屡遭贬谪, 却始终豁达自适, 笑对风波. 见你远来求学, 便与你讲讲这读书习字的道理." },
  [475] = { name="王安石", pai="254", hp=14000, maxhp=14000, dmg=0, def=0, exp=20000000, force=1, msg="王安石字介甫, 号半山, 抚州临川人. 他诗文峻拔, 位列唐宋八大家; 又力主变法, 欲富国强兵, 虽千万人非之而不改其志. 见你远来求学, 便与你讲讲这读书习字的道理." },
  [476] = { name="岳灵珊", pai="0", hp=1150, maxhp=1150, dmg=0, def=0, exp=1750000, force=82, msg="岳灵珊是华山派掌门岳不群与宁中则的独女, 自幼在华山长大, 剑法得父母真传. 她性子娇憨爽利, 与大师兄令狐冲一同创出「冲灵剑法」, 剑招里尽是少年时玉女峰的旧事." },
  [477] = { name="雪村萤子", pai="0", hp=14000, maxhp=14000, dmg=0, def=0, exp=14200000, force=272, msg="雪村萤子是浦饭幽助的青梅竹马. 她本是个普通的女高中生, 却在一次次被卷入灵异事件后觉醒了潜藏的灵力. 为了不再只是被人保护, 她开始认真修习——这份心意, 竟让她一路走到了这里." },
  [478] = { name="桑原和真", pai="0", hp=16200, maxhp=16200, dmg=0, def=0, exp=16400000, force=294, msg="桑原和真是浦饭幽助最好的朋友, 也是有名的不良少年. 他自小就能看见幽灵, 后来更觉醒了强大的灵力, 掌中凝出的灵剑足以斩妖除魔. 头脑算不上好使, 唯独这股不服输的劲头谁也比不了." },
  [479] = { name="幻海", pai="0", hp=18800, maxhp=18800, dmg=0, def=0, exp=19000000, force=320, msg="幻海是灵光波动拳的传人, 也是浦饭幽助与桑原和真的授业恩师. 她将一生都献给了武学与灵力修行, 年事虽高, 一身灵光却依旧深不可测." },
  [1001] = { name="八卦门秘籍", pai="1", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一册边角磨得起毛的旧簿, 封皮上「混元一气」四字端正古朴, 内页朱笔勾画着内息周天的运转路线, 是八卦门历代掌门批注的内功总纲." },
  [1002] = { name="花间派秘籍", pai="2", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一册以素绢为面的薄簿, 扉页题着「三花聚顶」, 字迹娟秀如花间清露, 是花间派历代掌门相传的内功心法." },
  [1003] = { name="红莲教秘籍", pai="3", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一部以赤布为皮的经折, 封皮上绣着一朵烈焰红莲, 内记「普天同济」心法, 字字殷红如烙印, 是红莲教立教的根基." },
  [1004] = { name="伊贺谷秘籍", pai="4", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一卷桑皮纸誊就的卷轴, 墨迹深浅不一, 记着「扶桑忍术」的内息吐纳之法, 卷尾盖着历代伊贺上忍的印鉴." },
  [1005] = { name="太极门秘籍", pai="5", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一册线装的道门经卷, 封皮上「太极神功」四字笔走龙蛇, 内页绘着阴阳双鱼环抱之图, 是太极门代代相传的内功真诠." },
  [1006] = { name="雪山派秘籍", pai="6", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一册以雪绢包裹的簿子, 纸页间隐隐透着寒气, 记着「雪山内功」的行气法门, 相传抄录自雪山之巅的石壁古文." },
  [1007] = { name="兽王派秘籍", pai="7", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一册以兽皮为面的旧书, 封皮上烙着兽首图腾, 内记「龙象般若功」的修炼法门, 翻动时隐有低沉兽吼自纸页间传来." },
  [1008] = { name="八卦门石板", pai="1", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一方青石镌成的功法石碑, 碑面「混元一气」四字笔势浑厚, 笔画间隐有内力流转, 是八卦门先辈以内力刻成的内功总纲." },
  [1009] = { name="花间派石板", pai="2", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一方莹白石板, 碑上刻着「三花聚顶」心法, 刻痕细腻如簪花小楷, 是花间派历代掌门以指力刻下的内功传承." },
  [1010] = { name="红莲教石板", pai="3", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一方赤色石板, 碑首镌着一朵烈焰红莲, 碑文记「普天同济」心法, 字字入石三分, 是红莲教立教之基." },
  [1011] = { name="伊贺谷石板", pai="4", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一方墨色石板, 碑文以忍术秘语记着「扶桑忍术」的吐纳之法, 刻痕深浅相间, 是伊贺谷历代上忍的传承印记." },
  [1012] = { name="太极门石板", pai="5", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一方青灰石板, 碑上「太极神功」四字圆转如意, 碑心刻着阴阳双鱼环抱之图, 是太极门代代相传的内功真诠." },
  [1013] = { name="雪山派石板", pai="6", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一方寒气沁人的白玉石板, 碑文记「雪山内功」行气法门, 相传采自雪山之巅, 千年不化." },
  [1014] = { name="兽王派石板", pai="7", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一方粗糙的花岗石板, 碑首烙着兽首图腾, 碑文记「龙象般若功」修炼法门, 刻痕深峻如兽爪抓痕." },
  [1015] = { name="八卦门天书", pai="1", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一册云篆天书, 字迹如龙蛇盘绕非人间笔墨, 悟透者可通「混元一气」的至高境界, 是八卦门传说中的内功秘典." },
  [1016] = { name="花间派天书", pai="2", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一卷以天蚕丝织就的天书, 字随丝纹隐现, 记「三花聚顶」最高奥义, 是花间派可望不可即的内功圣典." },
  [1017] = { name="红莲教天书", pai="3", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一部以不知名兽皮装订的天书, 翻开时隐有红光流转, 记「普天同济」心法的究竟境界, 是红莲教代代供奉的圣物." },
  [1018] = { name="伊贺谷天书", pai="4", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一卷古奥的天书卷轴, 文字如鸟虫篆难以辨认, 记「扶桑忍术」的终极奥义, 相传自扶桑神域流出." },
  [1019] = { name="太极门天书", pai="5", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一册无字天书, 惟有心境澄澈者可见「太极神功」最高深的心法浮现纸上, 是太极门失传已久的至宝." },
  [1020] = { name="雪山派天书", pai="6", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一册冰晶封面的天书, 页页寒雾缭绕, 记「雪山内功」的臻极法门, 相传是雪山神女所遗." },
  [1021] = { name="兽王派天书", pai="7", hp=100, maxhp=100, dmg=0, def=0, exp=100, force=0, msg="一册以远古兽皮为页的天书, 字迹如万兽奔踏的足迹, 记「龙象般若功」的臻至境界, 是兽王派起源的传说." },
}
